def session_stats(**_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0541000" if __import__("os").path.isdir("./environment_mix/0541000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _month_key(dt):
        return f"{dt.year:04d}-{dt.month:02d}"

    def _json_size_bytes(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    projects = _load("projects.json")
    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")
    tool_results = _load("tool_results.json")

    # AUTH: must be associated with an active api_key and active project.
    active_pairs = []
    proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        pid = k.get("project_id")
        p = proj_by_id.get(pid)
        if p and p.get("status") == "active":
            active_pairs.append((p, k))

    # If no active project+key exists anywhere, reject without creating tool_requests row.
    if not active_pairs:
        return _err("UNAUTHORIZED", "No active API key and project context available.")

    project, api_key = active_pairs[0]
    project_id = project.get("id")
    api_key_id = api_key.get("id")

    # Determine "current session" context: use the most recent tool_request with a session_id for this key+project.
    latest = None
    for r in tool_requests:
        if not isinstance(r, dict):
            continue
        if r.get("project_id") != project_id:
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        sid = r.get("session_id")
        if sid is None:
            continue
        created = _parse_dt(r.get("created_at")) or datetime.datetime.min
        if latest is None or created > latest[0]:
            latest = (created, sid)

    if latest is None:
        return _err("UNAUTHORIZED", "No active session context found for this API key.")

    session_id = latest[1]

    # Compute session lifetime window: use earliest and latest request timestamps for this session_id (same project+key).
    session_created_times = []
    for r in tool_requests:
        if not isinstance(r, dict):
            continue
        if r.get("project_id") != project_id:
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        if r.get("session_id") != session_id:
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt:
            session_created_times.append(dt)
    if not session_created_times:
        return _err("UNAUTHORIZED", "Session context is invalid or has no tracked activity.")

    session_start = min(session_created_times)
    session_end = max(session_created_times)

    # Aggregate stats: counts by tool_name, total_response_bytes, total_failures, total_browser_actions.
    counts_by_tool = {}
    total_response_bytes = 0
    total_failures = 0
    # browser actions counted by tool_requests that correspond to scraping_browser_*? In this schema, browser actions are separate.
    browser_actions = _load("browser_actions.json")
    browser_sessions = _load("browser_sessions.json")

    # Requests in session window and matching session_id; "created_at is within session lifetime"
    # We treat lifetime as [session_start, session_end] inclusive for the current known window.
    req_ids = []
    for r in tool_requests:
        if not isinstance(r, dict):
            continue
        if r.get("project_id") != project_id or r.get("api_key_id") != api_key_id:
            continue
        if r.get("session_id") != session_id:
            continue
        dt = _parse_dt(r.get("created_at"))
        if not dt:
            continue
        if dt < session_start or dt > session_end:
            continue
        tn = r.get("tool_name")
        if isinstance(tn, str):
            counts_by_tool[tn] = counts_by_tool.get(tn, 0) + 1
        if r.get("status") == "failed":
            total_failures += 1
        rb = r.get("response_bytes")
        if isinstance(rb, int) and rb >= 0:
            total_response_bytes += rb
        req_ids.append(r.get("id"))

    # Total browser actions: actions tied to sessions whose session_id matches and within lifetime.
    # If session_id is null on browser_sessions, still try by api_key+project and time window.
    bs_ids = set()
    for s in browser_sessions:
        if not isinstance(s, dict):
            continue
        if s.get("project_id") != project_id:
            continue
        if s.get("api_key_id") != api_key_id:
            continue
        sid = s.get("session_id")
        if sid is not None and sid != session_id:
            continue
        created = _parse_dt(s.get("created_at"))
        if created and (created < session_start or created > session_end):
            continue
        bs_ids.add(s.get("id"))

    total_browser_actions = 0
    for a in browser_actions:
        if not isinstance(a, dict):
            continue
        if a.get("project_id") != project_id:
            continue
        if a.get("api_key_id") != api_key_id:
            continue
        if a.get("browser_session_id") in bs_ids:
            total_browser_actions += 1

    # Create tool_request row for session_stats (queued -> running -> succeeded), then tool_result row.
    now_iso = _now()
    req_id = _new_id("tr")
    req_row = {
        "id": req_id,
        "project_id": project_id,
        "api_key_id": api_key_id,
        "session_id": session_id,
        "tool_name": "session_stats",
        "status": "queued",
        "engine": None,
        "query": None,
        "cursor": None,
        "url": None,
        "keyword": None,
        "pages_to_search": None,
        "extraction_prompt": None,
        "first_name": None,
        "last_name": None,
        "num_of_reviews": None,
        "days_limit": None,
        "num_of_comments": None,
        "response_content_type": "application/json",
        "response_bytes": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Quota check before creating tool_requests row: monthly_request_quota + monthly_byte_quota
    now_dt = datetime.datetime.utcnow()
    mkey = _month_key(now_dt)

    # compute month usage for project
    month_req_count = 0
    month_resp_bytes = 0
    for r in tool_requests:
        if not isinstance(r, dict):
            continue
        if r.get("project_id") != project_id:
            continue
        dt = _parse_dt(r.get("created_at"))
        if not dt:
            continue
        if _month_key(dt) != mkey:
            continue
        month_req_count += 1
        rb = r.get("response_bytes")
        if isinstance(rb, int) and rb >= 0:
            month_resp_bytes += rb

    quota_req = project.get("monthly_request_quota")
    quota_bytes = project.get("monthly_byte_quota")
    if not isinstance(quota_req, int) or quota_req < 0:
        return _err("VALIDATION_ERROR", "Project monthly_request_quota is invalid.")
    if not isinstance(quota_bytes, int) or quota_bytes < 0:
        return _err("VALIDATION_ERROR", "Project monthly_byte_quota is invalid.")

    # session_stats will produce a small JSON result; estimate size pre-write for quota_bytes
    stats_payload = {
        "project_id": project_id,
        "api_key_id": api_key_id,
        "session_id": session_id,
        "session_start": session_start.replace(microsecond=0).isoformat() + "Z",
        "session_end": session_end.replace(microsecond=0).isoformat() + "Z",
        "counts_by_tool_name": counts_by_tool,
        "total_response_bytes": total_response_bytes,
        "total_failures": total_failures,
        "total_browser_actions": total_browser_actions,
    }
    estimated_bytes = _json_size_bytes(stats_payload)

    if month_req_count + 1 > quota_req or month_resp_bytes + estimated_bytes > quota_bytes:
        # Business rule says: exceeding quota yields a failed request with error_code='quota_exceeded'.
        # But also says: reject and no tool_requests row is created only for unauthorized; for quota we create failed request.
        req_row["status"] = "failed"
        req_row["error_code"] = "quota_exceeded"
        req_row["error_message"] = "Project quota exceeded."
        req_row["started_at"] = now_iso
        req_row["finished_at"] = now_iso
        req_row["updated_at"] = now_iso
        req_row["response_bytes"] = 0
        tool_requests.append(req_row)
        _save("tool_requests.json", tool_requests)
        return _err("QUOTA_EXCEEDED", "Project quota exceeded.", error_code="quota_exceeded")

    # Create queued row
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    # Transition queued -> running -> succeeded (legal)
    started_iso = _now()
    for r in tool_requests:
        if isinstance(r, dict) and r.get("id") == req_id:
            r["status"] = "running"
            r["started_at"] = started_iso
            r["updated_at"] = started_iso
            break
    _save("tool_requests.json", tool_requests)

    # Write result row (must exist for succeeded)
    res_id = _new_id("trr")
    fetched_iso = _now()
    res_row = {
        "id": res_id,
        "request_id": req_id,
        "result_kind": "session_stats_json",
        "sequence": 0,
        "source_url": None,
        "title": None,
        "description": None,
        "payload_text": None,
        "payload_json": stats_payload,
        "next_cursor": None,
        "cache_hit": True,
        "fetched_at": fetched_iso,
        "expires_at": None,
        "created_at": fetched_iso,
        "updated_at": fetched_iso,
    }
    tool_results.append(res_row)
    _save("tool_results.json", tool_results)

    # Finalize request succeeded with response_bytes
    finished_iso = _now()
    response_bytes = _json_size_bytes(stats_payload)
    for r in tool_requests:
        if isinstance(r, dict) and r.get("id") == req_id:
            r["status"] = "succeeded"
            r["finished_at"] = finished_iso
            r["updated_at"] = finished_iso
            r["response_bytes"] = response_bytes
            r["response_content_type"] = "application/json"
            break
    _save("tool_requests.json", tool_requests)

    # update api_key last_used_at
    api_key_updated = False
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = finished_iso
            k["updated_at"] = finished_iso
            api_key_updated = True
            break
    if api_key_updated:
        _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "request": {
            "id": req_id,
            "project_id": project_id,
            "api_key_id": api_key_id,
            "tool_name": "session_stats",
            "status": "succeeded",
            "created_at": req_row["created_at"],
            "started_at": started_iso,
            "finished_at": finished_iso,
            "response_bytes": response_bytes,
            "latency_ms": latency_ms,
        },
        "result": stats_payload,
    }

def web_data_amazon_product(url, **_extra):
    import json, os, datetime, time, uuid, re
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0541000" if __import__("os").path.isdir("./environment_mix/0541000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _month_key(dt):
        return f"{dt.year:04d}-{dt.month:02d}"

    def _json_size_bytes(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _valid_uri(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _is_amazon_host(host):
        if not isinstance(host, str):
            return False
        h = host.lower()
        return ("amazon." in h) or h.endswith("amazon.com") or h.endswith("amazon.co.uk") or h.endswith("amazon.de") or h.endswith("amazon.ca") or h.endswith("amazon.co.jp")

    t0 = time.time()

    # Validate input
    if not _valid_uri(url):
        return _err("VALIDATION_ERROR", "Invalid or missing url.")
    pu = urlparse(url)
    if not _is_amazon_host(pu.netloc):
        return _err("VALIDATION_ERROR", "url must be an Amazon domain.")
    if "/dp/" not in pu.path:
        return _err("VALIDATION_ERROR", "Amazon product url must include '/dp/'.")

    projects = _load("projects.json")
    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")
    tool_results = _load("tool_results.json")

    proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
    active_pairs = []
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        p = proj_by_id.get(k.get("project_id"))
        if p and p.get("status") == "active":
            active_pairs.append((p, k))
    if not active_pairs:
        return _err("UNAUTHORIZED", "No active API key and project context available.")

    project, api_key = active_pairs[0]
    project_id = project.get("id")
    api_key_id = api_key.get("id")

    now_dt = datetime.datetime.utcnow()
    mkey = _month_key(now_dt)

    # Quota check before creating tool_requests row
    month_req_count = 0
    month_resp_bytes = 0
    for r in tool_requests:
        if not isinstance(r, dict):
            continue
        if r.get("project_id") != project_id:
            continue
        dt = _parse_dt(r.get("created_at"))
        if not dt or _month_key(dt) != mkey:
            continue
        month_req_count += 1
        rb = r.get("response_bytes")
        if isinstance(rb, int) and rb >= 0:
            month_resp_bytes += rb

    quota_req = project.get("monthly_request_quota")
    quota_bytes = project.get("monthly_byte_quota")
    if not isinstance(quota_req, int) or quota_req < 0:
        return _err("VALIDATION_ERROR", "Project monthly_request_quota is invalid.")
    if not isinstance(quota_bytes, int) or quota_bytes < 0:
        return _err("VALIDATION_ERROR", "Project monthly_byte_quota is invalid.")

    # Search for cached web_data_json result for the same url and tool_name within expiry.
    # We locate prior requests with tool_name and url for this project, then check tool_results cache_hit+expires_at.
    now_iso = _now()
    now_dt2 = _parse_dt(now_iso) or now_dt
    cached_payload = None
    cached_expires = None
    cached_fetched = None
    for r in tool_requests:
        if not isinstance(r, dict):
            continue
        if r.get("project_id") != project_id:
            continue
        if r.get("tool_name") != "web_data_amazon_product":
            continue
        if r.get("url") != url:
            continue
        if r.get("status") != "succeeded":
            continue
        rid = r.get("id")
        # find a web_data_json result
        for trr in tool_results:
            if not isinstance(trr, dict):
                continue
            if trr.get("request_id") != rid:
                continue
            if trr.get("result_kind") != "web_data_json":
                continue
            if trr.get("cache_hit") is not True:
                continue
            exp = _parse_dt(trr.get("expires_at"))
            if exp is None:
                continue
            if exp >= now_dt2:
                cached_payload = trr.get("payload_json")
                cached_expires = trr.get("expires_at")
                cached_fetched = trr.get("fetched_at")
                break
        if cached_payload is not None:
            break

    # If not cached, attempt to retrieve a durable dataset record from any previous non-cache web_data_json result
    # (simulate durable dataset existence). If none exists, NOT_FOUND.
    durable_payload = None
    if cached_payload is None:
        for r in tool_requests:
            if not isinstance(r, dict):
                continue
            if r.get("project_id") != project_id:
                continue
            if r.get("tool_name") != "web_data_amazon_product":
                continue
            if r.get("url") != url:
                continue
            if r.get("status") != "succeeded":
                continue
            rid = r.get("id")
            for trr in tool_results:
                if not isinstance(trr, dict):
                    continue
                if trr.get("request_id") != rid:
                    continue
                if trr.get("result_kind") != "web_data_json":
                    continue
                pj = trr.get("payload_json")
                if pj is not None:
                    durable_payload = pj
                    break
            if durable_payload is not None:
                break

    # Create tool_request row queued
    req_id = _new_id("tr")
    req_row = {
        "id": req_id,
        "project_id": project_id,
        "api_key_id": api_key_id,
        "session_id": None,
        "tool_name": "web_data_amazon_product",
        "status": "queued",
        "engine": None,
        "query": None,
        "cursor": None,
        "url": url,
        "keyword": None,
        "pages_to_search": None,
        "extraction_prompt": None,
        "first_name": None,
        "last_name": None,
        "num_of_reviews": None,
        "days_limit": None,
        "num_of_comments": None,
        "response_content_type": "application/json",
        "response_bytes": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Quota enforcement (estimate bytes after we know payload); still must check request quota now.
    if month_req_count + 1 > quota_req:
        req_row["status"] = "failed"
        req_row["error_code"] = "quota_exceeded"
        req_row["error_message"] = "Project quota exceeded."
        req_row["started_at"] = now_iso
        req_row["finished_at"] = now_iso
        req_row["updated_at"] = now_iso
        req_row["response_bytes"] = 0
        tool_requests.append(req_row)
        _save("tool_requests.json", tool_requests)
        return _err("QUOTA_EXCEEDED", "Project quota exceeded.", error_code="quota_exceeded")

    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    # Move to running
    started_iso = _now()
    for r in tool_requests:
        if isinstance(r, dict) and r.get("id") == req_id:
            r["status"] = "running"
            r["started_at"] = started_iso
            r["updated_at"] = started_iso
            break
    _save("tool_requests.json", tool_requests)

    # Determine outcome + payload
    cache_hit = False
    expires_at = None
    fetched_at = _now()
    payload = None

    if cached_payload is not None:
        payload = cached_payload
        cache_hit = True
        expires_at = cached_expires
        fetched_at = cached_fetched or fetched_at
    elif durable_payload is not None:
        # Treat as fresh/durable fetch (not from cache)
        payload = durable_payload
        cache_hit = False
        expires_at = None
    else:
        # NOT_FOUND
        finished_iso = _now()
        for r in tool_requests:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "failed"
                r["error_code"] = "not_found"
                r["error_message"] = "No product record could be retrieved for the supplied URL."
                r["finished_at"] = finished_iso
                r["updated_at"] = finished_iso
                r["response_bytes"] = 0
                break
        _save("tool_requests.json", tool_requests)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "No product record could be retrieved for the supplied URL.", latency_ms=latency_ms)

    # Cache semantics: if cache_hit True, expires_at must be non-null
    if cache_hit and not expires_at:
        # enforce rule by failing request
        finished_iso = _now()
        for r in tool_requests:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "failed"
                r["error_code"] = "cache_invariant"
                r["error_message"] = "Cached response missing expires_at."
                r["finished_at"] = finished_iso
                r["updated_at"] = finished_iso
                r["response_bytes"] = 0
                break
        _save("tool_requests.json", tool_requests)
        return _err("CONFLICT", "Cache invariant violated (missing expires_at).")

    # Byte quota check with actual payload size
    response_bytes = _json_size_bytes(payload)
    if month_resp_bytes + response_bytes > quota_bytes:
        finished_iso = _now()
        for r in tool_requests:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "failed"
                r["error_code"] = "quota_exceeded"
                r["error_message"] = "Project quota exceeded."
                r["finished_at"] = finished_iso
                r["updated_at"] = finished_iso
                r["response_bytes"] = 0
                break
        _save("tool_requests.json", tool_requests)
        return _err("QUOTA_EXCEEDED", "Project quota exceeded.", error_code="quota_exceeded")

    # Create tool_result (write-once)
    res_id = _new_id("trr")
    created_iso = _now()
    res_row = {
        "id": res_id,
        "request_id": req_id,
        "result_kind": "web_data_json",
        "sequence": 0,
        "source_url": url,
        "title": None,
        "description": None,
        "payload_text": None,
        "payload_json": payload,
        "next_cursor": None,
        "cache_hit": bool(cache_hit),
        "fetched_at": fetched_at,
        "expires_at": expires_at,
        "created_at": created_iso,
        "updated_at": created_iso,
    }
    tool_results.append(res_row)
    _save("tool_results.json", tool_results)

    # Succeed request (must have at least one result)
    finished_iso = _now()
    for r in tool_requests:
        if isinstance(r, dict) and r.get("id") == req_id:
            r["status"] = "succeeded"
            r["finished_at"] = finished_iso
            r["updated_at"] = finished_iso
            r["response_bytes"] = response_bytes
            r["response_content_type"] = "application/json"
            break
    _save("tool_requests.json", tool_requests)

    # update api_key last_used_at
    for k in api_keys:
