def web_data_walmart_product(url, **_extra):
    import json, os, datetime, time, uuid
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0541000" if __import__("os").path.isdir("./environment_mix/0541000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _month_key(dt):
        return f"{dt.year:04d}-{dt.month:02d}"

    def _is_valid_uri(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urlparse(u)
        except Exception:
            return False
        if p.scheme not in ("http", "https"):
            return False
        if not p.netloc:
            return False
        return True

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _select_auth_context():
        projects = _load("projects.json")
        api_keys = _load("api_keys.json")
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
        # Find any active api key whose project is active
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            pid = k.get("project_id")
            p = proj_by_id.get(pid)
            if not p or p.get("status") != "active":
                continue
            return p, k
        return None, None

    def _log_request(tool_name, project_id, api_key_id, status, latency_ms, request_id=None, error_code=None, error_message=None, response_bytes=None):
        tr = _load("tool_requests.json")
        now = _now_iso()
        rid = request_id or _gen_id("tr")
        row = {
            "id": rid,
            "project_id": project_id,
            "api_key_id": api_key_id,
            "session_id": None,
            "tool_name": tool_name,
            "status": status,
            "engine": None,
            "query": None,
            "cursor": None,
            "url": url,
            "keyword": None,
            "pages_to_search": None,
            "extraction_prompt": None,
            "first_name": None,
            "last_name": None,
            "num_of_reviews": None,
            "days_limit": None,
            "num_of_comments": None,
            "response_content_type": "application/json" if status == "succeeded" else None,
            "response_bytes": response_bytes,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        tr.append(row)
        _save("tool_requests.json", tr)
        # update api key last_used_at on success auth (even if request fails/quotas, auth succeeded)
        keys = _load("api_keys.json")
        changed = False
        for k in keys:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                k["last_used_at"] = now
                k["updated_at"] = now
                changed = True
                break
        if changed:
            _save("api_keys.json", keys)
        return rid

    def _quota_check(project_id):
        projects = _load("projects.json")
        p = None
        for pr in projects:
            if isinstance(pr, dict) and pr.get("id") == project_id:
                p = pr
                break
        if not p:
            return _err("NOT_FOUND", "Project not found.")
        nowdt = datetime.datetime.utcnow()
        mk = _month_key(nowdt)

        tool_reqs = _load("tool_requests.json")
        month_reqs = 0
        month_bytes = 0
        for r in tool_reqs:
            if not isinstance(r, dict):
                continue
            if r.get("project_id") != project_id:
                continue
            ca = _parse_dt(r.get("created_at"))
            if not ca:
                continue
            if _month_key(ca) != mk:
                continue
            month_reqs += 1
            rb = r.get("response_bytes")
            if isinstance(rb, int) and rb >= 0:
                month_bytes += rb

        req_quota = p.get("monthly_request_quota")
        byte_quota = p.get("monthly_byte_quota")
        if not isinstance(req_quota, int) or req_quota < 0:
            return _err("VALIDATION_ERROR", "Project monthly_request_quota is invalid.")
        if not isinstance(byte_quota, int) or byte_quota < 0:
            return _err("VALIDATION_ERROR", "Project monthly_byte_quota is invalid.")

        if month_reqs >= req_quota:
            return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded.", error_code="quota_exceeded")
        if month_bytes >= byte_quota:
            return _err("QUOTA_EXCEEDED", "Monthly byte quota exceeded.", error_code="quota_exceeded")
        return None

    t0 = time.time()

    # Validate input
    if not _is_valid_uri(url):
        return _err("VALIDATION_ERROR", "url must be a valid http(s) URI.")
    u = url.strip()
    purl = urlparse(u)
    host = (purl.netloc or "").lower()
    if "walmart." not in host:
        return _err("VALIDATION_ERROR", "url must be a Walmart URL.")
    if "/ip/" not in (purl.path or ""):
        return _err("VALIDATION_ERROR", "Walmart product url must include '/ip/'.")

    # Authenticate (ambient): must have active api key + active project, otherwise reject and DO NOT create tool_requests row.
    project, api_key = _select_auth_context()
    if not project or not api_key:
        return _err("UNAUTHORIZED", "No active credentials available for this operation.")

    # Quota check before creating queued request
    qerr = _quota_check(project["id"])
    if qerr:
        # Business rule says exceeding quota yields a failed request with error_code='quota_exceeded'.
        latency_ms = int((time.time() - t0) * 1000)
        _log_request("web_data_walmart_product", project["id"], api_key["id"], "failed", latency_ms,
                     error_code=qerr["error"].get("error_code") or "quota_exceeded",
                     error_message=qerr["error"]["message"], response_bytes=0)
        return qerr

    # Create queued request row first
    latency_ms = int((time.time() - t0) * 1000)
    request_id = _gen_id("tr")
    _log_request("web_data_walmart_product", project["id"], api_key["id"], "queued", latency_ms, request_id=request_id)

    # Attempt to serve from cache: find succeeded request with same tool+url for this project that has unexpired cached result
    tool_reqs = _load("tool_requests.json")
    tool_results = _load("tool_results.json")
    nowdt = datetime.datetime.utcnow()

    def _find_cached_payload():
        req_ids = []
        for r in tool_reqs:
            if not isinstance(r, dict):
                continue
            if r.get("project_id") != project["id"]:
                continue
            if r.get("tool_name") != "web_data_walmart_product":
                continue
            if r.get("status") != "succeeded":
                continue
            if (r.get("url") or "") != u:
                continue
            req_ids.append(r.get("id"))
        # look for web_data_json results with cache_hit true and expires_at in future
        best = None
        best_fetched = None
        for res in tool_results:
            if not isinstance(res, dict):
                continue
            if res.get("request_id") not in req_ids:
                continue
            if res.get("result_kind") != "web_data_json":
                continue
            if res.get("cache_hit") is not True:
                continue
            exp = _parse_dt(res.get("expires_at"))
            if not exp or exp < nowdt:
                continue
            fet = _parse_dt(res.get("fetched_at")) or datetime.datetime.min
            if best is None or fet > best_fetched:
                best = res
                best_fetched = fet
        return best

    cached = _find_cached_payload()

    # If no cached result exists, we cannot scrape offline; return NOT_FOUND
    if not cached or not isinstance(cached.get("payload_json"), (dict, list)):
        # Mark request failed with required fields
        trs = _load("tool_requests.json")
        now = _now_iso()
        for r in trs:
            if isinstance(r, dict) and r.get("id") == request_id:
                # queued -> running -> failed transition; enforce transitions
                r["status"] = "running"
                r["started_at"] = now
                r["updated_at"] = now
                r["status"] = "failed"
                r["finished_at"] = now
                r["updated_at"] = now
                r["error_code"] = "not_found"
                r["error_message"] = "No Walmart product web-data record available for this URL."
                r["response_bytes"] = 0
                break
        _save("tool_requests.json", trs)
        return _err("NOT_FOUND", "No Walmart product record could be retrieved for the supplied URL.")

    # Create a new result row for this request (write-once)
    now = _now_iso()
    result_id = _gen_id("trr")
    payload = cached["payload_json"]
    # cache semantics: if served from cache, cache_hit true and expires_at non-null
    expires_at = cached.get("expires_at")
    if expires_at is None:
        # cannot claim cache without expires_at
        expires_at = (datetime.datetime.utcnow() + datetime.timedelta(hours=24)).replace(microsecond=0).isoformat() + "Z"
    fetched_at = now
    res_row = {
        "id": result_id,
        "request_id": request_id,
        "result_kind": "web_data_json",
        "sequence": 0,
        "source_url": u,
        "title": None,
        "description": None,
        "payload_text": None,
        "payload_json": payload,
        "next_cursor": None,
        "cache_hit": True,
        "fetched_at": fetched_at,
        "expires_at": expires_at,
        "created_at": now,
        "updated_at": now,
    }
    tool_results.append(res_row)
    _save("tool_results.json", tool_results)

    # Complete request as succeeded, ensure at least one result exists
    trs = _load("tool_requests.json")
    response_bytes = len(json.dumps(payload, ensure_ascii=False).encode("utf-8"))
    for r in trs:
        if isinstance(r, dict) and r.get("id") == request_id:
            r["status"] = "running"
            r["started_at"] = r.get("started_at") or now
            r["updated_at"] = now
            r["status"] = "succeeded"
            r["finished_at"] = now
            r["updated_at"] = now
            r["response_content_type"] = "application/json"
            r["response_bytes"] = response_bytes
            r["error_code"] = None
            r["error_message"] = None
            break
    _save("tool_requests.json", trs)

    return {
        "request": {"id": request_id, "status": "succeeded"},
        "data": payload,
        "meta": {"cache_hit": True, "expires_at": expires_at},
    }

