            row["response_content_type"] = response_ct
        if response_b is not None:
            row["response_bytes"] = response_b
        if error_code is not None:
            row["error_code"] = error_code
        if error_message is not None:
            row["error_message"] = error_message
        row["updated_at"] = now_iso
        for i, tr in enumerate(tool_requests):
            if tr.get("id") == row["id"]:
                tool_requests[i] = row
                _save("tool_requests.json", tool_requests)
                return None
        return _err("NOT_FOUND", "tool_request not found")

    def _write_result(req_id, payload_json, cache_hit, expires_at):
        if cache_hit and not expires_at:
            return _err("VALIDATION_ERROR", "Cached web_data results must have expires_at")
        for r in tool_results:
            if r.get("request_id") == req_id and r.get("result_kind") == "web_data_json" and r.get("sequence") == 0:
                return _err("CONFLICT", "Result already exists for this request (write-once)")
        row = {
            "id": _new_id("trsl"),
            "request_id": req_id,
            "result_kind": "web_data_json",
            "sequence": 0,
            "source_url": url,
            "title": None,
            "description": None,
            "payload_text": None,
            "payload_json": payload_json,
            "next_cursor": None,
            "cache_hit": bool(cache_hit),
            "fetched_at": now_iso,
            "expires_at": _iso(expires_at),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_results.append(row)
        _save("tool_results.json", tool_results)
        return row

    # Quotas
    pid = project_row["id"]
    start_month = now.replace(day=1, hour=0, minute=0, second=0)
    monthly_reqs = 0
    monthly_bytes = 0
    for tr in tool_requests:
        if tr.get("project_id") != pid:
            continue
        ca = _parse_iso(tr.get("created_at"))
        if ca and ca >= start_month:
            monthly_reqs += 1
            rb = tr.get("response_bytes")
            if isinstance(rb, int) and rb >= 0:
                monthly_bytes += rb

    if monthly_reqs + 1 > int(project_row.get("monthly_request_quota", 0)):
        req = _create_request()
        _transition(req, "running")
        _transition(req, "failed", error_code="quota_exceeded", error_message="Monthly request quota exceeded")
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded")

    if monthly_bytes > int(project_row.get("monthly_byte_quota", 0)):
        req = _create_request()
        _transition(req, "running")
        _transition(req, "failed", error_code="quota_exceeded", error_message="Monthly byte quota exceeded")
        return _err("QUOTA_EXCEEDED", "Monthly byte quota exceeded")

    req = _create_request()

    # last_used_at
    for i, k in enumerate(api_keys):
        if k.get("id") == api_key_row["id"]:
            api_keys[i] = {**k, "last_used_at": now_iso, "updated_at": now_iso}
            _save("api_keys.json", api_keys)
            break

    _transition(req, "running")

    # cache lookup
    cached = None
    for r in tool_results:
        if r.get("result_kind") != "web_data_json":
            continue
        if (r.get("source_url") or "") != url:
            continue
        trq = next((tr for tr in tool_requests if tr.get("id") == r.get("request_id")), None)
        if not trq or trq.get("project_id") != pid or trq.get("tool_name") != "web_data_instagram_posts":
            continue
        exp = _parse_iso(r.get("expires_at"))
        if exp and exp >= now:
            cached = r
            break

    if cached:
        payload = cached.get("payload_json")
        response_bytes = len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) if payload is not None else 0
        _write_result(req["id"], payload_json=payload, cache_hit=True, expires_at=_parse_iso(cached.get("expires_at")) or (now + datetime.timedelta(hours=24)))
        _transition(req, "succeeded", response_ct="application/json", response_b=response_bytes)
        _ = t0
        return {"data": payload, "meta": {"cache_hit": True, "request_id": req["id"]}}

    # acquire
    p = urlparse(url)
    parts = [x for x in (p.path or "").split("/") if x]
    kind = parts[0] if len(parts) > 0 else None
    shortcode = parts[1] if len(parts) > 1 else None
    payload = {
        "source": "acquired",
        "dataset": "instagram_post",
        "url": url,
        "post_kind": kind,
        "shortcode": shortcode,
        "fetched_at": now_iso,
    }
    response_bytes = len(json.dumps(payload, ensure_ascii=False).encode("utf-8"))
    _write_result(req["id"], payload_json=payload, cache_hit=False, expires_at=None)
    _transition(req, "succeeded", response_ct="application/json", response_b=response_bytes)
    _ = t0
    return {"data": payload, "meta": {"cache_hit": False, "request_id": req["id"]}}

def web_data_tiktok_shop(url, **_extra):
    import json, os, datetime, time, uuid, re
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0541000" if __import__("os").path.isdir("./environment_mix/0541000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _month_key(dt):
        return dt.strftime("%Y-%m")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_valid_uri(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _resolve_auth():
        # Ambient authentication: pick any api_key that is active and whose project is active.
        projects = _load("projects.json")
        api_keys = _load("api_keys.json")
        proj_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            pid = k.get("project_id")
            p = proj_by_id.get(pid)
            if not p or p.get("status") != "active":
                continue
            return p, k
        return None, None

    def _project_usage_for_month(project_id, month):
        tool_requests = _load("tool_requests.json")
        total_requests = 0
        total_bytes = 0
        for r in tool_requests:
            if not isinstance(r, dict):
                continue
            if r.get("project_id") != project_id:
                continue
            created = _parse_dt(r.get("created_at"))
            if not created:
                continue
            if _month_key(created) != month:
                continue
            total_requests += 1
            rb = r.get("response_bytes")
            if isinstance(rb, int) and rb >= 0:
                total_bytes += rb
        return total_requests, total_bytes

    def _log_tool_request(req_row):
        tool_requests = _load("tool_requests.json")
        tool_requests.append(req_row)
        _save("tool_requests.json", tool_requests)

    def _update_tool_request(req_id, patch):
        tool_requests = _load("tool_requests.json")
        hit = None
        for r in tool_requests:
            if isinstance(r, dict) and r.get("id") == req_id:
                hit = r
                break
        if not hit:
            return False
        hit.update(patch)
        hit["updated_at"] = now_iso
        _save("tool_requests.json", tool_requests)
        return True

    def _create_tool_result(result_row):
        tool_results = _load("tool_results.json")
        # enforce unique(request_id, result_kind, sequence)
        for tr in tool_results:
            if not isinstance(tr, dict):
                continue
            if tr.get("request_id") == result_row.get("request_id") and tr.get("result_kind") == result_row.get("result_kind") and tr.get("sequence") == result_row.get("sequence"):
                return False
        tool_results.append(result_row)
        _save("tool_results.json", tool_results)
        return True

    def _find_cached_web_data(tool_name, project_id, source_url):
        tool_requests = _load("tool_requests.json")
        tool_results = _load("tool_results.json")
        req_by_id = {r.get("id"): r for r in tool_requests if isinstance(r, dict)}
        candidates = []
        for res in tool_results:
            if not isinstance(res, dict):
                continue
            if res.get("result_kind") != "web_data_json":
                continue
            if res.get("source_url") != source_url:
                continue
            req = req_by_id.get(res.get("request_id"))
            if not req or req.get("project_id") != project_id:
                continue
            if req.get("tool_name") != tool_name:
                continue
            if req.get("status") != "succeeded":
                continue
            exp = _parse_dt(res.get("expires_at"))
            if exp is None:
                continue
            if exp >= now:
                candidates.append((exp, res, req))
        if not candidates:
            return None
        # choose the one with latest expires_at
        candidates.sort(key=lambda x: x[0], reverse=True)
        return candidates[0][1]

    def _validate_tiktok_shop_url(u):
        if not _is_valid_uri(u):
            return False, "url must be a valid http(s) URI"
        p = urlparse(u)
        host = (p.netloc or "").lower()
        if "tiktok.com" not in host and "tiktokshop" not in host:
            return False, "url must be a TikTok Shop URL"
        # Best-effort: require something that looks like product detail (/view/ or /product/ or /item/ etc.)
        path = (p.path or "").lower()
        if not any(seg in path for seg in ("/product", "/item", "/shop", "/i/", "/p/")):
            # allow query-based product ids
            q = (p.query or "").lower()
            if "product" not in q and "item" not in q and "sku" not in q and "id=" not in q:
                return False, "url must look like a TikTok Shop product URL"
        return True, None

    # Validate input
    if url is None:
        return _err("VALIDATION_ERROR", "Missing required parameter: url")
    if not isinstance(url, str):
        return _err("VALIDATION_ERROR", "url must be a string")
    ok, emsg = _validate_tiktok_shop_url(url)
    if not ok:
        return _err("VALIDATION_ERROR", emsg)

    # Auth (ambient)
    project, api_key = _resolve_auth()
    if not project or not api_key:
        return _err("UNAUTHORIZED", "Invalid or missing API key context")

    # Quota checks (request + byte quota) before creating queued request
    month = _month_key(now)
    used_req, used_bytes = _project_usage_for_month(project["id"], month)
    mrq = project.get("monthly_request_quota")
    mbq = project.get("monthly_byte_quota")
    if not isinstance(mrq, int) or mrq < 0:
        return _err("VALIDATION_ERROR", "Project monthly_request_quota is invalid")
    if not isinstance(mbq, int) or mbq < 0:
        return _err("VALIDATION_ERROR", "Project monthly_byte_quota is invalid")
    if used_req >= mrq:
        # Do not create tool_requests row per rule.
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded", error_code="quota_exceeded")
    if used_bytes >= mbq:
        return _err("QUOTA_EXCEEDED", "Monthly byte quota exceeded", error_code="quota_exceeded")

    # Create tool_request (queued -> running -> succeeded/failed)
    req_id = _gen_id("treq")
    req_row = {
        "id": req_id,
        "project_id": project["id"],
        "api_key_id": api_key["id"],
        "session_id": _extra.get("session_id") if isinstance(_extra.get("session_id"), str) else None,
        "tool_name": "web_data_tiktok_shop",
        "status": "queued",
        "engine": None,
        "query": None,
        "cursor": None,
        "url": url,
        "keyword": None,
        "pages_to_search": None,
        "extraction_prompt": None,
        "first_name": None,
        "last_name": None,
        "num_of_reviews": None,
        "days_limit": None,
        "num_of_comments": None,
        "response_content_type": None,
        "response_bytes": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    _log_tool_request(req_row)

    # Mark api_key last_used_at
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    # Transition to running
    _update_tool_request(req_id, {"status": "running", "started_at": now_iso})

    # Attempt cache hit
    cached = _find_cached_web_data("web_data_tiktok_shop", project["id"], url)
    if cached:
        payload = cached.get("payload_json")
        resp_bytes = len(json.dumps(payload, ensure_ascii=False).encode("utf-8")) if payload is not None else 0
        _update_tool_request(req_id, {
            "status": "succeeded",
            "finished_at": now_iso,
            "response_content_type": "application/json",
            "response_bytes": resp_bytes,
        })
        result_row = {
            "id": _gen_id("tres"),
            "request_id": req_id,
            "result_kind": "web_data_json",
            "sequence": 0,
            "source_url": url,
            "title": None,
            "description": None,
            "payload_text": None,
            "payload_json": payload,
            "next_cursor": None,
            "cache_hit": True,
            "fetched_at": now_iso,
            "expires_at": cached.get("expires_at"),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        if not _create_tool_result(result_row):
            _update_tool_request(req_id, {
                "status": "failed",
                "finished_at": now_iso,
                "error_code": "conflict",
                "error_message": "Result already exists for this request",
            })
            return _err("CONFLICT", "Result already exists for this request")
        return {
            "request": _load("tool_requests.json")[-1] if _load("tool_requests.json") else req_row,
            "result": result_row,
            "meta": {
                "project_id": project["id"],
                "api_key_id": api_key["id"],
                "cache_hit": True,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        }

    # No cache available; offline backend cannot fetch real web data => fail as NOT_FOUND (resource cannot be fetched)
    _update_tool_request(req_id, {
        "status": "failed",
        "finished_at": now_iso,
        "error_code": "not_found",
        "error_message": "Product could not be retrieved (no cached dataset available offline).",
        "response_content_type": "application/json",
        "response_bytes": 0,
    })
    return _err("NOT_FOUND", "Product could not be retrieved")

