        p = urlparse(u)
        host = (p.netloc or "").lower()
        if host.startswith("www."):
            host = host[4:]
        # support x.com and twitter.com
        if host not in ("x.com", "twitter.com"):
            return False
        path = p.path or ""
        # Typical: /{user}/status/{id}
        m = re.match(r"^/([^/]+)/status/(\d+)", path)
        if not m:
            return False
        return True

    def _extract_ids(u):
        p = urlparse(u)
        m = re.match(r"^/([^/]+)/status/(\d+)", p.path or "")
        if not m:
            return None, None
        return m.group(1), m.group(2)

    def _canon(u):
        p = urlparse(u)
        host = (p.netloc or "").lower()
        if host.startswith("www."):
            host = host[4:]
        path = p.path or "/"
        # drop query/fragment
        return f"{p.scheme.lower()}://{host}{path}"

    ok, msg = _uri_ok(url)
    if not ok:
        return _err("VALIDATION_ERROR", msg)
    if not _supported(url):
        return _err("VALIDATION_ERROR", "url is not a supported X post URL")

    projects = _load("projects.json")
    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")
    tool_results = _load("tool_results.json")

    # Auth ambient
    project = None
    api_key = None
    for k in api_keys:
        if k.get("status") != "active":
            continue
        pid = k.get("project_id")
        if not pid:
            continue
        p = next((pp for pp in projects if pp.get("id") == pid), None)
        if not p or p.get("status") != "active":
            continue
        project, api_key = p, k
        break
    if not project or not api_key:
        return _err("UNAUTHORIZED", "No active credentials available for this operation")

    # Quota enforcement (requests + bytes)
    mk = _month_key(now)
    reqs_this_month = 0
    bytes_this_month = 0
    for r in tool_requests:
        if r.get("project_id") != project.get("id"):
            continue
        dt = _parse_dt(r.get("created_at"))
        if not dt or _month_key(dt) != mk:
            continue
        reqs_this_month += 1
        rb = r.get("response_bytes")
        if isinstance(rb, int) and rb >= 0:
            bytes_this_month += rb

    if reqs_this_month + 1 > int(project.get("monthly_request_quota", 0)):
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded", error_code="quota_exceeded")
    if bytes_this_month > int(project.get("monthly_byte_quota", 0)):
        return _err("QUOTA_EXCEEDED", "Monthly byte quota exceeded", error_code="quota_exceeded")

    # Create request queued then running
    req_id = _gen_id("tr")
    tr = {
        "id": req_id,
        "project_id": project["id"],
        "api_key_id": api_key["id"],
        "session_id": None,
        "tool_name": "web_data_x_posts",
        "status": "queued",
        "engine": None,
        "query": None,
        "cursor": None,
        "url": url,
        "keyword": None,
        "pages_to_search": None,
        "extraction_prompt": None,
        "first_name": None,
        "last_name": None,
        "num_of_reviews": None,
        "days_limit": None,
        "num_of_comments": None,
        "response_content_type": None,
        "response_bytes": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    tool_requests.append(tr)
    started = datetime.datetime.now(datetime.timezone.utc)
    tr["status"] = "running"
    tr["started_at"] = started.isoformat()
    tr["updated_at"] = tr["started_at"]

    canon_url = _canon(url)
    username, post_id = _extract_ids(url)

    # NOT_FOUND semantics: if we have historical failures for same canonical url, return NOT_FOUND.
    # This is the only offline way to model "URL not found" without external fetch.
    prev_failed = False
    for r in tool_requests:
        if r.get("project_id") != project["id"]:
            continue
        if r.get("tool_name") != "web_data_x_posts":
            continue
        if r.get("url") != url and _canon(r.get("url") or "") != canon_url:
            continue
        if r.get("status") == "failed" and r.get("error_code") == "not_found":
            prev_failed = True
            break

    if prev_failed:
        finished = datetime.datetime.now(datetime.timezone.utc)
        tr["status"] = "failed"
        tr["error_code"] = "not_found"
        tr["error_message"] = "The requested post URL was not found"
        tr["response_content_type"] = "application/json"
        tr["response_bytes"] = len(json.dumps({"error": tr["error_message"]}, ensure_ascii=False).encode("utf-8"))
        tr["finished_at"] = finished.isoformat()
        tr["updated_at"] = tr["finished_at"]
        api_key["last_used_at"] = finished.isoformat()
        api_key["updated_at"] = finished.isoformat()
        _save("tool_requests.json", tool_requests)
        _save("api_keys.json", api_keys)
        return _err("NOT_FOUND", tr["error_message"], error_code="not_found")

    # Cache lookup (unexpired)
    cache_row = None
    for res in tool_results:
        if res.get("result_kind") != "web_data_json":
            continue
        if (res.get("source_url") or "") != canon_url:
            continue
        rid = res.get("request_id")
        rr = next((x for x in tool_requests if x.get("id") == rid), None)
        if not rr:
            continue
        if rr.get("project_id") != project["id"]:
            continue
        if rr.get("tool_name") != "web_data_x_posts":
            continue
        if rr.get("status") != "succeeded":
            continue
        exp = _parse_dt(res.get("expires_at"))
        if exp and exp >= now:
            cache_row = res
            break

    fetched_at = datetime.datetime.now(datetime.timezone.utc)
    cache_hit = bool(cache_row)
    if cache_hit:
        payload = cache_row.get("payload_json")
        if not isinstance(payload, dict):
            payload = {"data": payload}
        payload_out = payload
        expires_at = cache_row.get("expires_at") or (now + datetime.timedelta(hours=2)).isoformat()
    else:
        payload_out = {
            "source": "x",
            "entity_type": "post",
            "id": post_id,
            "author_username": username,
            "canonical_url": canon_url,
            "fetched_at": fetched_at.isoformat(),
        }
        expires_at = None

    # Cache semantics: if cache_hit then expires_at must be non-null
    if cache_hit and not expires_at:
        expires_at = (now + datetime.timedelta(hours=2)).isoformat()

    res_id = _gen_id("trr")
    result = {
        "id": res_id,
        "request_id": req_id,
        "result_kind": "web_data_json",
        "sequence": 0,
        "source_url": canon_url,
        "title": None,
        "description": None,
        "payload_text": None,
        "payload_json": payload_out,
        "next_cursor": None,
        "cache_hit": True if cache_hit else False,
        "fetched_at": fetched_at.isoformat(),
        "expires_at": expires_at if cache_hit else None,
        "created_at": fetched_at.isoformat(),
        "updated_at": fetched_at.isoformat(),
    }
    tool_results.append(result)

    finished = datetime.datetime.now(datetime.timezone.utc)
    body_bytes = len(json.dumps(payload_out, ensure_ascii=False).encode("utf-8"))
    tr["status"] = "succeeded"
    tr["response_content_type"] = "application/json"
    tr["response_bytes"] = body_bytes
    tr["finished_at"] = finished.isoformat()
    tr["updated_at"] = tr["finished_at"]

    api_key["last_used_at"] = finished.isoformat()
    api_key["updated_at"] = finished.isoformat()

    _save("tool_requests.json", tool_requests)
    _save("tool_results.json", tool_results)
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "request": tr,
        "data": payload_out,
        "meta": {
            "cache_hit": result["cache_hit"],
            "expires_at": result["expires_at"],
            "latency_ms": latency_ms,
        },
    }

