    # Create request queued -> running
    tr = _record_tool_request(project.get("id"), api_key.get("id"), "queued", {"url": url, "num_of_comments": num_of_comments, "response_content_type": "application/json"})
    tr_id = tr["id"]

    tool_requests = _load("tool_requests.json")
    for r in tool_requests:
        if isinstance(r, dict) and r.get("id") == tr_id:
            r["status"] = "running"
            r["started_at"] = now_iso
            r["updated_at"] = now_iso
            break
    _save("tool_requests.json", tool_requests)

    _update_api_key_last_used(api_key.get("id"))

    cached = _find_cached_result(project.get("id"), url, num_of_comments)
    tool_results = _load("tool_results.json")

    if cached:
