            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_requests.append(row)
        _save("tool_requests.json", tool_requests)
        return row

    def _find_cached_result(project_id, canonical_url):
        tool_requests = _load("tool_requests.json")
        tool_results = _load("tool_results.json")
        succeeded = []
        for r in tool_requests:
            if not isinstance(r, dict):
                continue
            if r.get("project_id") != project_id: continue
            if r.get("tool_name") != tool_name: continue
            if r.get("status") != "succeeded": continue
            if r.get("url") != canonical_url: continue
            ca = _parse_dt(r.get("created_at")) or datetime.datetime.min
            succeeded.append((ca, r.get("id")))
        if not succeeded:
            return None
        succeeded.sort(reverse=True, key=lambda x: x[0])
        req_id = succeeded[0][1]
        rows = [res for res in tool_results if isinstance(res, dict) and res.get("request_id") == req_id and res.get("result_kind") == "web_data_json" and res.get("sequence") == 0]
        if not rows:
            return None
        res = rows[0]
        if not res.get("cache_hit"):
            return None
        exp = _parse_dt(res.get("expires_at"))
        if not exp:
            return None
        if now <= exp:
            return res
        return None

    ok, msg = _validate_uri(url)
    if not ok:
        return _err("VALIDATION_ERROR", msg)
    if not _is_supported_youtube_video(url):
        return _err("VALIDATION_ERROR", "url must be a supported YouTube video URL")

    project, api_key = _pick_auth_context()
    if not project or not api_key:
        return _err("UNAUTHORIZED", "No active API key/project context available")

    tool_requests = _load("tool_requests.json")
