        "full_page": None,
        "status": "running",
        "result_ref": None,
        "error_message": None,
        "started_at": now_iso,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    browser_actions.append(action)

    # Apply state update
    for s in browser_sessions:
        if isinstance(s, dict) and s.get("id") == session.get("id"):
            s["history"] = history
            s["history_index"] = hi - 1
            s["current_url"] = target_url
            s["action_count"] = int(s.get("action_count") or 0) + 1
            s["last_activity_at"] = now_iso
            s["updated_at"] = now_iso
            session = s
            break

    finished_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for a in browser_actions:
        if isinstance(a, dict) and a.get("id") == action_id:
            a["status"] = "succeeded"
            a["finished_at"] = finished_iso
            a["updated_at"] = finished_iso
            break

    _save("browser_actions.json", browser_actions)
    _save("browser_sessions.json", browser_sessions)

    resp = {"browser_session": session, "action": next((a for a in browser_actions if isinstance(a, dict) and a.get("id") == action_id), None)}
    rb = _json_size_bytes(resp)
    _log_request(project.get("id"), key_row.get("id"), "succeeded", response_bytes=rb)

    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    return {"browser_session": session, "action": resp["action"], "latency_ms": int((time.time() - t0) * 1000)}

