    if not isinstance(target_url, str) or not target_url:
        _log_request(project.get("id"), key_row.get("id"), "failed", response_bytes=0, error_code="no_history", error_message="Forward history entry is not available.")
        return _err("NOT_FOUND", "No forward entry available in session history.")

