    project, key_row, session = _pick_auth_context()
    if not project or not key_row:
        return _err("UNAUTHORIZED", "Authentication rule: no active api_keys record for an active project with an active browser session is available.")
    if not session:
        return _err("VALIDATION_ERROR", "There is no active session context for this call.")

    # Quota enforcement
    reqs, bytes_used, actions_used = _project_usage(project.get("id"))
    mreq = project.get("monthly_request_quota")
    mbytes = project.get("monthly_byte_quota")
    mactions = project.get("monthly_browser_action_quota")
    if isinstance(mreq, int) and mreq >= 0 and reqs + 1 > mreq:
        _log_failed_quota_request(project.get("id"), key_row.get("id"), "Monthly request quota exceeded for project.")
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded for project.", error_code="quota_exceeded")
    if isinstance(mbytes, int) and mbytes >= 0 and bytes_used > mbytes:
        _log_failed_quota_request(project.get("id"), key_row.get("id"), "Monthly byte quota exceeded for project.")
        return _err("QUOTA_EXCEEDED", "Monthly byte quota exceeded for project.", error_code="quota_exceeded")
    if isinstance(mactions, int) and mactions >= 0 and actions_used + 1 > mactions:
        _log_failed_quota_request(project.get("id"), key_row.get("id"), "Monthly browser action quota exceeded for project.")
        return _err("QUOTA_EXCEEDED", "Monthly browser action quota exceeded for project.", error_code="quota_exceeded")

    current_url = session.get("current_url")
    if not isinstance(current_url, str) or not current_url.strip():
        _log_request(project.get("id"), key_row.get("id"), "failed", error_code="no_page", error_message="Current page is not available.")
        return _err("NOT_FOUND", "Current page is not available (session has no current_url).")

    # Very lightweight "selector resolution":
    # - Accept common patterns produced by our links tool (a[data-synth='i'], a[data-history-index='i'])
    # - Otherwise, treat as a click that does not navigate (still succeeds), unless it looks invalid.
    nav_url = None
    if selector.startswith("a[data-synth='") and selector.endswith("']"):
        idx = selector[len("a[data-synth='"):-2]
        if idx.isdigit():
            i = int(idx)
            common = ["/", "/pricing", "/docs", "/contact", "#top"]
            if 0 <= i < len(common):
                nav_url = urljoin(current_url, common[i])
            else:
                _log_request(project.get("id"), key_row.get("id"), "failed", error_code="no_element", error_message="No element matches the selector.")
                return _err("NOT_FOUND", "No element matches the selector.")
        else:
            return _err("VALIDATION_ERROR", "selector is invalid")
    elif selector.startswith("a[data-history-index='") and selector.endswith("']"):
        idx = selector[len("a[data-history-index='"):-2]
        if idx.isdigit():
            i = int(idx)
            hist = session.get("history")
            if isinstance(hist, list) and 0 <= i < len(hist) and isinstance(hist[i], str) and hist[i].strip():
                nav_url = hist[i].strip()
            else:
                _log_request(project.get("id"), key_row.get("id"), "failed", error_code="no_element", error_message="No element matches the selector.")
                return _err("NOT_FOUND", "No element matches the selector.")
        else:
            return _err("VALIDATION_ERROR", "selector is invalid")

    existing_action_ids = {a.get("id") for a in browser_actions if isinstance(a, dict)}
    action_id = _gen_id("bd_act", existing_action_ids)
    action = {
        "id": action_id,
        "browser_session_id": session.get("id"),
        "project_id": project.get("id"),
        "api_key_id": key_row.get("id"),
        "action_type": "scraping_browser_click",
        "url": None,
        "selector": selector,
        "text": None,
        "submit": None,
        "timeout_ms": None,
        "full_page": None,
        "status": "running",
        "result_ref": None,
        "error_message": None,
        "started_at": now_iso,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    browser_actions.append(action)

    # If click navigates, apply same semantics as navigate (truncate forward history)
    if nav_url:
        history = session.get("history")
        if not isinstance(history, list):
            history = []
        hi = session.get("history_index")
        if not isinstance(hi, int) or hi < 0:
            hi = len(history) - 1 if history else 0
        if hi < len(history) - 1:
            history = history[:hi + 1]
        history.append(nav_url)
        hi = len(history) - 1

        for s in browser_sessions:
            if isinstance(s, dict) and s.get("id") == session.get("id"):
                s["current_url"] = nav_url
                s["history"] = history
                s["history_index"] = hi
                s["action_count"] = int(s.get("action_count") or 0) + 1
                s["last_activity_at"] = now_iso
                s["updated_at"] = now_iso
                session = s
                break
    else:
        for s in browser_sessions:
            if isinstance(s, dict) and s.get("id") == session.get("id"):
                s["action_count"] = int(s.get("action_count") or 0) + 1
                s["last_activity_at"] = now_iso
                s["updated_at"] = now_iso
                session = s
                break

    finished_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for a in browser_actions:
        if isinstance(a, dict) and a.get("id") == action_id:
            a["status"] = "succeeded"
            a["finished_at"] = finished_iso
            a["updated_at"] = finished_iso
            break

    _save("browser_actions.json", browser_actions)
    _save("browser_sessions.json", browser_sessions)

    resp = {"browser_session": session, "action": next((a for a in browser_actions if isinstance(a, dict) and a.get("id") == action_id), None)}
    rb = _json_size_bytes(resp)
    _log_request(project.get("id"), key_row.get("id"), "succeeded", response_bytes=rb)

    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    return {"browser_session": session, "action": resp["action"], "latency_ms": int((time.time() - t0) * 1000)}

def scraping_browser_screenshot(full_page=None, **_extra):
    import json, os, datetime, uuid, time, base64
    import hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0541000" if __import__("os").path.isdir("./environment_mix/0541000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix, existing_ids):
        rid = f"{prefix}_{uuid.uuid4().hex}"
        while rid in existing_ids:
            rid = f"{prefix}_{uuid.uuid4().hex}"
        return rid

    def _month_key(dt):
        return dt.strftime("%Y-%m")

    def _json_size_bytes(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    if full_page is None:
        full_page = False
    if not isinstance(full_page, bool):
        return _err("VALIDATION_ERROR", "full_page must be a boolean")

    projects = _load("projects.json")
    api_keys = _load("api_keys.json")
    browser_sessions = _load("browser_sessions.json")
    browser_actions = _load("browser_actions.json")
    tool_requests = _load("tool_requests.json")

    def _pick_auth_context():
        active_projects = {p.get("id"): p for p in projects if isinstance(p, dict) and p.get("status") == "active"}
        candidate_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("project_id") in active_projects]
        if not candidate_keys:
            return None, None, None
        sessions_ok = []
        for s in browser_sessions:
            if not isinstance(s, dict) or s.get("status") != "active":
                continue
            pid = s.get("project_id")
            if pid not in active_projects:
                continue
            exp = _parse_dt(s.get("expires_at"))
            last = _parse_dt(s.get("last_activity_at"))
            if not exp or now > exp or (last and last > now):
                continue
            sessions_ok.append(s)
        if not sessions_ok:
            return None, None, None
        key_by_id = {k.get("id"): k for k in candidate_keys}
        for s in sessions_ok:
            kid = s.get("api_key_id")
            if kid and kid in key_by_id and key_by_id[kid].get("project_id") == s.get("project_id"):
                return active_projects[s.get("project_id")], key_by_id[kid], s
        keys_by_project = {}
        for k in candidate_keys:
            keys_by_project.setdefault(k.get("project_id"), []).append(k)
        for s in sessions_ok:
            pid = s.get("project_id")
            ks = keys_by_project.get(pid) or []
            if ks:
                return active_projects[pid], ks[0], s
        return None, None, None

    def _project_usage(project_id):
        mk = _month_key(now)
        reqs = 0
        bytes_used = 0
        actions_used = 0
        for tr in tool_requests:
            if not isinstance(tr, dict) or tr.get("project_id") != project_id:
                continue
            ca = _parse_dt(tr.get("created_at"))
            if not ca or _month_key(ca) != mk:
                continue
            reqs += 1
            rb = tr.get("response_bytes")
            if isinstance(rb, int) and rb >= 0:
                bytes_used += rb
        for ba in browser_actions:
            if not isinstance(ba, dict) or ba.get("project_id") != project_id:
                continue
            ca = _parse_dt(ba.get("created_at"))
            if not ca or _month_key(ca) != mk:
                continue
            actions_used += 1
        return reqs, bytes_used, actions_used

    def _log_failed_quota_request(project_id, api_key_id, msg):
        existing = {r.get("id") for r in tool_requests if isinstance(r, dict)}
        rid = _gen_id("bd_req", existing)
        row = {
            "id": rid,
            "project_id": project_id,
            "api_key_id": api_key_id,
            "session_id": None,
            "tool_name": "scrape_as_html",
            "status": "failed",
            "engine": None,
            "query": None,
            "cursor": None,
            "url": None,
            "keyword": None,
            "pages_to_search": None,
            "extraction_prompt": None,
            "first_name": None,
            "last_name": None,
            "num_of_reviews": None,
            "days_limit": None,
            "num_of_comments": None,
            "response_content_type": None,
            "response_bytes": 0,
            "error_code": "quota_exceeded",
            "error_message": msg,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_requests.append(row)
        _save("tool_requests.json", tool_requests)
        return row

    def _log_request(project_id, api_key_id, status, response_bytes=0, error_code=None, error_message=None):
        existing = {r.get("id") for r in tool_requests if isinstance(r, dict)}
        rid = _gen_id("bd_req", existing)
        row = {
            "id": rid,
            "project_id": project_id,
            "api_key_id": api_key_id,
            "session_id": None,
            "tool_name": "scrape_as_html",
            "status": status,
            "engine": None,
            "query": None,
            "cursor": None,
            "url": None,
            "keyword": None,
            "pages_to_search": None,
            "extraction_prompt": None,
            "first_name": None,
            "last_name": None,
            "num_of_reviews": None,
            "days_limit": None,
            "num_of_comments": None,
            "response_content_type": "application/json",
            "response_bytes": int(response_bytes) if isinstance(response_bytes, int) and response_bytes >= 0 else 0,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_requests.append(row)
        _save("tool_requests.json", tool_requests)
        return row

    project, key_row, session = _pick_auth_context()
    if not project or not key_row:
        return _err("UNAUTHORIZED", "Authentication rule: no active api_keys record for an active project with an active browser session is available.")
    if not session:
        return _err("VALIDATION_ERROR", "There is no active session context for this call.")

    current_url = session.get("current_url")
    if not isinstance(current_url, str) or not current_url.strip():
        _log_request(project.get("id"), key_row.get("id"), "failed", error_code="no_page", error_message="Current page is not available.")
        return _err("NOT_FOUND", "Current page is not available (session has no current_url).")

    # Quota enforcement
    reqs, bytes_used, actions_used = _project_usage(project.get("id"))
    mreq = project.get("monthly_request_quota")
    mbytes = project.get("monthly_byte_quota")
    mactions = project.get("monthly_browser_action_quota")
    if isinstance(mreq, int) and mreq >= 0 and reqs + 1 > mreq:
        _log_failed_quota_request(project.get("id"), key_row.get("id"), "Monthly request quota exceeded for project.")
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded for project.", error_code="quota_exceeded")
    if isinstance(mbytes, int) and mbytes >= 0 and bytes_used > mbytes:
        _log_failed_quota_request(project.get("id"), key_row.get("id"), "Monthly byte quota exceeded for project.")
        return _err("QUOTA_EXCEEDED", "Monthly byte quota exceeded for project.", error_code="quota_exceeded")
    if isinstance(mactions, int) and mactions >= 0 and actions_used + 1 > mactions:
        _log_failed_quota_request(project.get("id"), key_row.get("id"), "Monthly browser action quota exceeded for project.")
        return _err("QUOTA_EXCEEDED", "Monthly browser action quota exceeded for project.", error_code="quota_exceeded")

    # Create deterministic pseudo-image bytes (offline)
    seed = (current_url + ("|full" if full_page else "|view")).encode("utf-8")
    digest = hashlib.sha256(seed).digest()
    # Make it "bigger" for full_page
    blob = digest * (120 if full_page else 40)  # 32*40=1280 bytes, 32*120=3840 bytes
    b64 = base64.b64encode(blob).decode("ascii")

    existing_action_ids = {a.get("id") for a in browser_actions if isinstance(a, dict)}
    action_id = _gen_id("bd_act", existing_action_ids)
    action = {
        "id": action_id,
        "browser_session_id": session.get("id"),
        "project_id": project.get("id"),
        "api_key_id": key_row.get("id"),
        "action_type": "scraping_browser_screenshot",
        "url": None,
        "selector": None,
        "text": None,
        "submit": None,
        "timeout_ms": None,
        "full_page": full_page,
        "status": "succeeded",
        "result_ref": b64[:128],  # short inline ref
        "error_message": None,
        "started_at": now_iso,
        "finished_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    browser_actions.append(action)
    _save("browser_actions.json", browser_actions)

    for s in browser_sessions:
        if isinstance(s, dict) and s.get("id") == session.get("id"):
            s["action_count"] = int(s.get("action_count") or 0) + 1
            s["last_activity_at"] = now_iso
            s["updated_at"] = now_iso
            session = s
            break
    _save("browser_sessions.json", browser_sessions)

    resp = {
        "content_type": "image/png",
        "screenshot_base64": b64,
        "browser_session": session,
        "action": action,
    }
    rb = _json_size_bytes(resp)
    _log_request(project.get("id"), key_row.get("id"), "succeeded", response_bytes=rb)

    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    return {"content_type": "image/png", "screenshot_base64": b64, "browser_session": session, "action": action, "latency_ms": int((time.time() - t0) * 1000)}

