    mreq = project.get("monthly_request_quota")
    mbytes = project.get("monthly_byte_quota")
    mactions = project.get("monthly_browser_action_quota")
    if isinstance(mreq, int) and mreq >= 0 and reqs + 1 > mreq:
        _log_failed_quota_request(project.get("id"), key_row.get("id"), "Monthly request quota exceeded for project.")
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded for project.", error_code="quota_exceeded")
    if isinstance(mbytes, int) and mbytes >= 0 and bytes_used > mbytes:
        _log_failed_quota_request(project.get("id"), key_row.get("id"), "Monthly byte quota exceeded for project.")
        return _err("QUOTA_EXCEEDED", "Monthly byte quota exceeded for project.", error_code="quota_exceeded")
    if isinstance(mactions, int) and mactions >= 0 and actions_used + 1 > mactions:
        _log_failed_quota_request(project.get("id"), key_row.get("id"), "Monthly browser action quota exceeded for project.")
        return _err("QUOTA_EXCEEDED", "Monthly browser action quota exceeded for project.", error_code="quota_exceeded")

    existing_action_ids = {a.get("id") for a in browser_actions if isinstance(a, dict)}
    action_id = _gen_id("bd_act", existing_action_ids)
    action = {
        "id": action_id,
        "browser_session_id": session.get("id"),
        "project_id": project.get("id"),
        "api_key_id": key_row.get("id"),
        "action_type": "scraping_browser_scroll",
        "url": None,
        "selector": None,
        "text": None,
        "submit": None,
        "timeout_ms": None,
        "full_page": None,
        "status": "succeeded",
        "result_ref": "scrolled_to_bottom",
        "error_message": None,
        "started_at": now_iso,
        "finished_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    browser_actions.append(action)
    _save("browser_actions.json", browser_actions)

    for s in browser_sessions:
        if isinstance(s, dict) and s.get("id") == session.get("id"):
            s["action_count"] = int(s.get("action_count") or 0) + 1
            s["last_activity_at"] = now_iso
            s["updated_at"] = now_iso
            session = s
            break
    _save("browser_sessions.json", browser_sessions)

    resp = {"browser_session": session, "action": action}
    rb = _json_size_bytes(resp)
    _log_request(project.get("id"), key_row.get("id"), "succeeded", response_bytes=rb)

    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    return {"browser_session": session, "action": action, "latency_ms": int((time.time() - t0) * 1000)}

def scraping_browser_scroll_to(selector, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0541000" if __import__("os").path.isdir("./environment_mix/0541000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix, existing_ids):
        rid = f"{prefix}_{uuid.uuid4().hex}"
        while rid in existing_ids:
            rid = f"{prefix}_{uuid.uuid4().hex}"
        return rid

    def _month_key(dt):
        return dt.strftime("%Y-%m")

    def _json_size_bytes(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    if not isinstance(selector, str) or not selector.strip():
        return _err("VALIDATION_ERROR", "selector must be a non-empty string")
    selector = selector.strip()
    if len(selector) > 1000:
        return _err("VALIDATION_ERROR", "selector is too long")

    projects = _load("projects.json")
    api_keys = _load("api_keys.json")
    browser_sessions = _load("browser_sessions.json")
    browser_actions = _load("browser_actions.json")
    tool_requests = _load("tool_requests.json")

    def _pick_auth_context():
        active_projects = {p.get("id"): p for p in projects if isinstance(p, dict) and p.get("status") == "active"}
        candidate_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("project_id") in active_projects]
        if not candidate_keys:
            return None, None, None
        sessions_ok = []
        for s in browser_sessions:
            if not isinstance(s, dict) or s.get("status") != "active":
                continue
            pid = s.get("project_id")
            if pid not in active_projects:
                continue
            exp = _parse_dt(s.get("expires_at"))
            last = _parse_dt(s.get("last_activity_at"))
            if not exp or now > exp or (last and last > now):
                continue
            sessions_ok.append(s)
        if not sessions_ok:
            return None, None, None
        key_by_id = {k.get("id"): k for k in candidate_keys}
        for s in sessions_ok:
            kid = s.get("api_key_id")
            if kid and kid in key_by_id and key_by_id[kid].get("project_id") == s.get("project_id"):
                return active_projects[s.get("project_id")], key_by_id[kid], s
        keys_by_project = {}
        for k in candidate_keys:
            keys_by_project.setdefault(k.get("project_id"), []).append(k)
        for s in sessions_ok:
            pid = s.get("project_id")
            ks = keys_by_project.get(pid) or []
            if ks:
                return active_projects[pid], ks[0], s
        return None, None, None

    def _project_usage(project_id):
        mk = _month_key(now)
        reqs = 0
        bytes_used = 0
        actions_used = 0
        for tr in tool_requests:
            if not isinstance(tr, dict) or tr.get("project_id") != project_id:
                continue
            ca = _parse_dt(tr.get("created_at"))
            if not ca or _month_key(ca) != mk:
                continue
            reqs += 1
            rb = tr.get("response_bytes")
            if isinstance(rb, int) and rb >= 0:
                bytes_used += rb
        for ba in browser_actions:
            if not isinstance(ba, dict) or ba.get("project_id") != project_id:
                continue
            ca = _parse_dt(ba.get("created_at"))
            if not ca or _month_key(ca) != mk:
                continue
            actions_used += 1
        return reqs, bytes_used, actions_used

    def _log_failed_quota_request(project_id, api_key_id, msg):
        existing = {r.get("id") for r in tool_requests if isinstance(r, dict)}
        rid = _gen_id("bd_req", existing)
        row = {
            "id": rid,
            "project_id": project_id,
            "api_key_id": api_key_id,
            "session_id": None,
            "tool_name": "scrape_as_html",
            "status": "failed",
            "engine": None,
            "query": None,
            "cursor": None,
            "url": None,
            "keyword": None,
            "pages_to_search": None,
            "extraction_prompt": None,
            "first_name": None,
            "last_name": None,
            "num_of_reviews": None,
            "days_limit": None,
            "num_of_comments": None,
            "response_content_type": None,
            "response_bytes": 0,
            "error_code": "quota_exceeded",
            "error_message": msg,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_requests.append(row)
        _save("tool_requests.json", tool_requests)
        return row

    def _log_request(project_id, api_key_id, status, response_bytes=0, error_code=None, error_message=None):
        existing = {r.get("id") for r in tool_requests if isinstance(r, dict)}
        rid = _gen_id("bd_req", existing)
        row = {
            "id": rid,
            "project_id": project_id,
            "api_key_id": api_key_id,
            "session_id": None,
            "tool_name": "scrape_as_html",
            "status": status,
            "engine": None,
            "query": None,
            "cursor": None,
            "url": None,
            "keyword": None,
            "pages_to_search": None,
            "extraction_prompt": None,
            "first_name": None,
            "last_name": None,
            "num_of_reviews": None,
            "days_limit": None,
            "num_of_comments": None,
            "response_content_type": "application/json",
            "response_bytes": int(response_bytes) if isinstance(response_bytes, int) and response_bytes >= 0 else 0,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_requests.append(row)
        _save("tool_requests.json", tool_requests)
        return row

    project, key_row, session = _pick_auth_context()
    if not project or not key_row:
        return _err("UNAUTHORIZED", "Authentication rule: no active api_keys record for an active project with an active browser session is available.")
    if not session:
        return _err("VALIDATION_ERROR", "There is no active session context for this call.")

    # Quota enforcement
    reqs, bytes_used, actions_used = _project_usage(project.get("id"))
    mreq = project.get("monthly_request_quota")
    mbytes = project.get("monthly_byte_quota")
    mactions = project.get("monthly_browser_action_quota")
    if isinstance(mreq, int) and mreq >= 0 and reqs + 1 > mreq:
        _log_failed_quota_request(project.get("id"), key_row.get("id"), "Monthly request quota exceeded for project.")
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded for project.", error_code="quota_exceeded")
    if isinstance(mbytes, int) and mbytes >= 0 and bytes_used > mbytes:
        _log_failed_quota_request(project.get("id"), key_row.get("id"), "Monthly byte quota exceeded for project.")
        return _err("QUOTA_EXCEEDED", "Monthly byte quota exceeded for project.", error_code="quota_exceeded")
    if isinstance(mactions, int) and mactions >= 0 and actions_used + 1 > mactions:
        _log_failed_quota_request(project.get("id"), key_row.get("id"), "Monthly browser action quota exceeded for project.")
        return _err("QUOTA_EXCEEDED", "Monthly browser action quota exceeded for project.", error_code="quota_exceeded")

    # Selector existence can't be verified offline; apply limited rules:
    # If selector looks clearly invalid, reject; otherwise succeed.
    if selector in (".", "#", "*") or selector.startswith("??"):
        _log_request(project.get("id"), key_row.get("id"), "failed", error_code="no_element", error_message="No element matches the selector.")
        return _err("NOT_FOUND", "No element matches the selector on the current page.")

    existing_action_ids = {a.get("id") for a in browser_actions if isinstance(a, dict)}
    action_id = _gen_id("bd_act", existing_action_ids)
    action = {
        "id": action_id,
        "browser_session_id": session.get("id"),
        "project_id": project.get("id"),
        "api_key_id": key_row.get("id"),
        "action_type": "scraping_browser_scroll_to",
        "url": None,
        "selector": selector,
        "text": None,
        "submit": None,
        "timeout_ms": None,
        "full_page": None,
        "status": "succeeded",
        "result_ref": f"scrolled_to:{selector[:120]}",
        "error_message": None,
        "started_at": now_iso,
        "finished_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    browser_actions.append(action)
    _save("browser_actions.json", browser_actions)

    for s in browser_sessions:
        if isinstance(s, dict) and s.get("id") == session.get("id"):
            s["action_count"] = int(s.get("action_count") or 0) + 1
            s["last_activity_at"] = now_iso
            s["updated_at"] = now_iso
            session = s
            break
    _save("browser_sessions.json", browser_sessions)

    resp = {"browser_session": session, "action": action}
    rb = _json_size_bytes(resp)
    _log_request(project.get("id"), key_row.get("id"), "succeeded", response_bytes=rb)

    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    return {"browser_session": session, "action": action, "latency_ms": int((time.time() - t0) * 1000)}

def whoami(api_key, **_extra):
    import json, os, datetime, base64, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0541000" if __import__("os").path.isdir("./environment_mix/0541000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow()
    now_iso = now.replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    projects = _load("projects.json")
    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")

    def _record_attempt(resolved_project_id, resolved_api_key_id, status, error_code=None, error_message=None, response_bytes=0):
        # whoami has no tool_name enum entry in tool_requests, so record dynamics via a lightweight self-log file
        # while still enforcing quotas via tool_requests (which is the canonical usage source).
        # We will append to service_audit.json (not in schema) without breaking schema constraints.
        audit = _load("service_audit.json")
        latency_ms = int((time.time() - t0) * 1000)
        audit.append({
            "id": f"a_{int(time.time()*1000)}_{len(audit)+1}",
            "endpoint": "whoami",
            "project_id": resolved_project_id,
            "api_key_id": resolved_api_key_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "response_bytes": int(response_bytes or 0),
            "latency_ms": latency_ms,
            "created_at": now_iso,
        })
        _save("service_audit.json", audit)

    # Authenticate by matching plaintext (client-visible) against id or key_prefix (since plaintext isn't stored) is impossible.
    # Business rule says plaintext is provided; store has key_hash only. We therefore accept:
    #  - api_key equals api_keys.id (client may pass id)
    #  - api_key begins with key_prefix and hashes to key_hash (if key_hash stores a hash of the full key)
    # But we cannot verify hash algorithm; vendor rule: never compare against stored hash/ciphertext in a way that can never pass.
    # We'll implement best-effort: try common SHA256/SHA1/MD5 of the provided api_key and compare to key_hash.
    candidate_rows = []
    k = api_key.strip()

    hashes = []
    try:
        b = k.encode("utf-8")
        hashes = [
            hashlib.sha256(b).hexdigest(),
            hashlib.sha1(b).hexdigest(),
            hashlib.md5(b).hexdigest(),
            base64.b64encode(hashlib.sha256(b).digest()).decode("ascii"),
            base64.b64encode(hashlib.sha1(b).digest()).decode("ascii"),
            base64.b64encode(hashlib.md5(b).digest()).decode("ascii"),
        ]
    except Exception:
        hashes = []

    for r in api_keys:
        if r.get("status") != "active":
            continue
        if not isinstance(r.get("project_id"), str) or not r.get("project_id"):
            continue
        if k == r.get("id"):
            candidate_rows.append(r); continue
        kp = r.get("key_prefix")
        if isinstance(kp, str) and kp and k.startswith(kp):
            candidate_rows.append(r); continue
        kh = r.get("key_hash")
        if isinstance(kh, str) and kh and kh in hashes:
            candidate_rows.append(r); continue

    # From candidates, pick one whose project is active
    resolved_key = None
    resolved_project = None
    for r in candidate_rows:
        pid = r["project_id"]
        p = next((x for x in projects if x.get("id") == pid), None)
        if p and p.get("status") == "active":
            resolved_key = r
            resolved_project = p
            break

    if not resolved_key or not resolved_project:
        _record_attempt(None, None, "unauthorized", error_code="unauthorized", error_message="Invalid/revoked API key or inactive project")
        return _err("UNAUTHORIZED", "Invalid/revoked API key or inactive project")

    # Update last_used_at
    updated = False
    for r in api_keys:
        if r.get("id") == resolved_key.get("id"):
            r["last_used_at"] = now_iso
            r["updated_at"] = now_iso
            updated = True
            break
    if updated:
        _save("api_keys.json", api_keys)

    # Compute month-to-date usage from tool_requests for this project
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    month_start = datetime.datetime(now.year, now.month, 1)
    mtd_requests = 0
    mtd_bytes = 0
    mtd_browser_actions = 0
    mtd_failures = 0

    browser_action_tool_prefix = "scraping_browser_"

    for tr in tool_requests:
        if tr.get("project_id") != resolved_project["id"]:
            continue
        created = _parse_dt(tr.get("created_at"))
        if not created or created < month_start or created > now:
            continue
        mtd_requests += 1
        rb = tr.get("response_bytes")
        if isinstance(rb, int) and rb >= 0:
            mtd_bytes += rb
        if tr.get("status") == "failed":
            mtd_failures += 1
        # Browser actions are counted elsewhere; tool_requests doesn't include them.
        # We'll compute from browser_actions collection for accuracy.
    browser_actions = _load("browser_actions.json")
    for ba in browser_actions:
        if ba.get("project_id") != resolved_project["id"]:
            continue
        created = _parse_dt(ba.get("created_at"))
        if not created or created < month_start or created > now:
            continue
        mtd_browser_actions += 1

    quotas = {
        "monthly_request_quota": resolved_project.get("monthly_request_quota"),
        "monthly_byte_quota": resolved_project.get("monthly_byte_quota"),
        "monthly_browser_action_quota": resolved_project.get("monthly_browser_action_quota"),
    }
    # Validate quota fields (schema constraints)
    for kq in ("monthly_request_quota", "monthly_byte_quota", "monthly_browser_action_quota"):
        if not isinstance(quotas.get(kq), int) or quotas[kq] < 0:
            _record_attempt(resolved_project["id"], resolved_key["id"], "failed", error_code="invalid_project_quota", error_message=f"Project has invalid {kq}")
            return _err("CONFLICT", f"Project has invalid quota configuration: {kq}")

    remaining = {
        "monthly_request_quota_remaining": max(0, quotas["monthly_request_quota"] - mtd_requests),
        "monthly_byte_quota_remaining": max(0, quotas["monthly_byte_quota"] - mtd_bytes),
        "monthly_browser_action_quota_remaining": max(0, quotas["monthly_browser_action_quota"] - mtd_browser_actions),
    }
    over = {
        "monthly_request_quota_over": max(0, mtd_requests - quotas["monthly_request_quota"]),
        "monthly_byte_quota_over": max(0, mtd_bytes - quotas["monthly_byte_quota"]),
        "monthly_browser_action_quota_over": max(0, mtd_browser_actions - quotas["monthly_browser_action_quota"]),
    }

    body = {
        "api_key": {
            "id": resolved_key.get("id"),
            "name": resolved_key.get("name"),
            "status": resolved_key.get("status"),
            "key_prefix": resolved_key.get("key_prefix"),
            "last_used_at": resolved_key.get("last_used_at"),
            "created_at": resolved_key.get("created_at"),
            "updated_at": resolved_key.get("updated_at"),
        },
        "project": {
            "id": resolved_project.get("id"),
            "name": resolved_project.get("name"),
            "status": resolved_project.get("status"),
            "plan": resolved_project.get("plan"),
            "created_at": resolved_project.get("created_at"),
            "updated_at": resolved_project.get("updated_at"),
        },
        "entitlements": {
            "plan": resolved_project.get("plan"),
            "features": {
                "search_engine": True,
                "scrape_as_markdown": True,
                "scrape_as_html": True,
                "extract": True,
                "web_data": True,
                "scraping_browser": True,
                "session_stats": True,
            },
        },
        "month_to_date": {
            "month_start": month_start.replace(microsecond=0).isoformat() + "Z",
            "requests": mtd_requests,
            "response_bytes": mtd_bytes,
            "browser_actions": mtd_browser_actions,
            "failures": mtd_failures,
        },
        "quotas": quotas | remaining | over,
    }

    # Estimate response bytes and log call
    try:
        response_bytes = len(json.dumps(body, ensure_ascii=False).encode("utf-8"))
    except Exception:
        response_bytes = 0
    _record_attempt(resolved_project["id"], resolved_key["id"], "succeeded", response_bytes=response_bytes)
    return {"data": body}

def list_tool_requests(api_key, status=None, tool_name=None, session_id=None, created_after=None, created_before=None, page_size=None, cursor=None, **_extra):
    import json, os, datetime, base64, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0541000" if __import__("os").path.isdir("./environment_mix/0541000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow()
    now_iso = now.replace(microsecond=0).isoformat() + "Z"

    # Validation
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None and status not in allowed_status:
        return _err("VALIDATION_ERROR", "Invalid status", allowed=list(allowed_status))

    allowed_tool_name = {
        "search_engine", "scrape_as_markdown", "scrape_as_html", "extract", "session_stats",
        "web_data_amazon_product", "web_data_amazon_product_reviews", "web_data_amazon_product_search",
        "web_data_google_maps_reviews", "web_data_youtube_comments", "web_data_youtube_video"
    }
    if tool_name is not None and tool_name not in allowed_tool_name:
        return _err("VALIDATION_ERROR", "Invalid tool_name", allowed=sorted(list(allowed_tool_name)))

    if session_id is not None and (not isinstance(session_id, str) or not session_id.strip()):
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string when provided")

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an RFC3339 date-time string")
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            raise ValueError(f"{field} must be an RFC3339 date-time string")

    try:
        ca = _parse_dt(created_after, "created_after")
        cb = _parse_dt(created_before, "created_before")
    except ValueError as e:
        return _err("VALIDATION_ERROR", str(e))
    if ca and cb and ca > cb:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before")

    projects = _load("projects.json")
    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")

    # Authenticate best-effort (same strategy as whoami)
    k = api_key.strip()
    hashes = []
    try:
        b = k.encode("utf-8")
        hashes = [
            hashlib.sha256(b).hexdigest(),
            hashlib.sha1(b).hexdigest(),
            hashlib.md5(b).hexdigest(),
            base64.b64encode(hashlib.sha256(b).digest()).decode("ascii"),
            base64.b64encode(hashlib.sha1(b).digest()).decode("ascii"),
            base64.b64encode(hashlib.md5(b).digest()).decode("ascii"),
        ]
    except Exception:
        hashes = []

    candidates = []
    for r in api_keys:
        if r.get("status") != "active":
            continue
        if k == r.get("id"):
            candidates.append(r); continue
        kp = r.get("key_prefix")
        if isinstance(kp, str) and kp and k.startswith(kp):
            candidates.append(r); continue
        kh = r.get("key_hash")
        if isinstance(kh, str) and kh and kh in hashes:
            candidates.append(r); continue

    resolved_key = None
    resolved_project = None
    for r in candidates:
        p = next((x for x in projects if x.get("id") == r.get("project_id")), None)
        if p and p.get("status") == "active":
            resolved_key = r
            resolved_project = p
            break
    if not resolved_key or not resolved_project:
        audit = _load("service_audit.json")
        audit.append({
            "id": f"a_{int(time.time()*1000)}_{len(audit)+1}",
            "endpoint": "list_tool_requests",
            "project_id": None,
            "api_key_id": None,
            "status": "unauthorized",
            "error_code": "unauthorized",
            "error_message": "Invalid/revoked API key or inactive project",
            "response_bytes": 0,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("service_audit.json", audit)
        return _err("UNAUTHORIZED", "Invalid/revoked API key or inactive project")

    # Update last_used_at
    for r in api_keys:
        if r.get("id") == resolved_key.get("id"):
            r["last_used_at"] = now_iso
            r["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    # Pagination cursor: base64("created_at|id")
    def _decode_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(c.encode("ascii") + b"===").decode("utf-8")
            parts = raw.split("|", 1)
            if len(parts) != 2:
                return _err("VALIDATION_ERROR", "Invalid cursor")
            dt = parts[0]
            rid = parts[1]
            ss = dt[:-1] if dt.endswith("Z") else dt
            d = datetime.datetime.fromisoformat(ss)
            return (d, rid)
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    dc = _decode_cursor(cursor)
    if isinstance(dc, dict) and "error" in dc:
        return dc
    after_dt_id = dc  # (dt, id) as exclusive boundary for next page

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    # Filter
    rows = []
    for tr in tool_requests:
        if tr.get("project_id") != resolved_project.get("id"):
            continue
        if status is not None and tr.get("status") != status:
            continue
        if tool_name is not None and tr.get("tool_name") != tool_name:
            continue
        if session_id is not None and tr.get("session_id") != session_id:
            continue
        cdt = _parse_iso(tr.get("created_at"))
        if ca and (not cdt or cdt < ca):
            continue
        if cb and (not cdt or cdt > cb):
            continue
        rows.append(tr)

    # Sort newest-first by created_at then id
    def _sort_key(tr):
        d = _parse_iso(tr.get("created_at")) or datetime.datetime(1970, 1, 1)
        return (d, str(tr.get("id") or ""))

    rows.sort(key=_sort_key, reverse=True)

    # Apply cursor boundary (exclusive)
    if after_dt_id:
        boundary_dt, boundary_id = after_dt_id
        filtered = []
        for tr in rows:
            d = _parse_iso(tr.get("created_at")) or datetime.datetime(1970, 1, 1)
            tid = str(tr.get("id") or "")
            # keep items strictly older than boundary in our (dt desc, id desc) ordering
            if d < boundary_dt:
                filtered.append(tr)
            elif d == boundary_dt and tid < boundary_id:
                filtered.append(tr)
        rows = filtered

    page = rows[:page_size]
    has_more = len(rows) > page_size

    next_cursor = None
    if has_more and page:
        last = page[-1]
        ldt = last.get("created_at") or now_iso
        lid = str(last.get("id") or "")
        try:
            next_cursor = base64.urlsafe_b64encode(f"{ldt}|{lid}".encode("utf-8")).decode("ascii").rstrip("=")
        except Exception:
            next_cursor = None

    resp = {
        "data": page,
        "meta": {
            "total_matched": len(rows),
            "returned": len(page),
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
        }
    }

    # Audit
    try:
        response_bytes = len(json.dumps(resp, ensure_ascii=False).encode("utf-8"))
    except Exception:
        response_bytes = 0
    audit = _load("service_audit.json")
    audit.append({
        "id": f"a_{int(time.time()*1000)}_{len(audit)+1}",
        "endpoint": "list_tool_requests",
        "project_id": resolved_project.get("id"),
        "api_key_id": resolved_key.get("id"),
        "status": "succeeded",
        "error_code": None,
        "error_message": None,
        "response_bytes": response_bytes,
        "latency_ms": int((time.time() - t0) * 1000),
        "created_at": now_iso,
    })
    _save("service_audit.json", audit)

    return resp

def list_tool_results(api_key, request_id, result_kind=None, page_size=None, cursor=None, **_extra):
    import json, os, datetime, base64, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0541000" if __import__("os").path.isdir("./environment_mix/0541000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow()
    now_iso = now.replace(microsecond=0).isoformat() + "Z"

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(request_id, str) or not request_id.strip():
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string")

    allowed_kind = {"serp_item", "document_markdown", "document_html", "extracted_json", "web_data_json", "session_stats_json"}
    if result_kind is not None and result_kind not in allowed_kind:
        return _err("VALIDATION_ERROR", "Invalid result_kind", allowed=sorted(list(allowed_kind)))

    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or page_size < 1 or page_size > 500:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 500")

    projects = _load("projects.json")
    api_keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")
    tool_results = _load("tool_results.json")

    # Authenticate
    k = api_key.strip()
    hashes = []
    try:
        b = k.encode("utf-8")
        hashes = [
            hashlib.sha256(b).hexdigest(),
            hashlib.sha1(b).hexdigest(),
            hashlib.md5(b).hexdigest(),
            base64.b64encode(hashlib.sha256(b).digest()).decode("ascii"),
            base64.b64encode(hashlib.sha1(b).digest()).decode("ascii"),
            base64.b64encode(hashlib.md5(b).digest()).decode("ascii"),
        ]
    except Exception:
        hashes = []

    candidates = []
    for r in api_keys:
        if r.get("status") != "active":
            continue
        if k == r.get("id"):
            candidates.append(r); continue
        kp = r.get("key_prefix")
        if isinstance(kp, str) and kp and k.startswith(kp):
            candidates.append(r); continue
        kh = r.get("key_hash")
        if isinstance(kh, str) and kh and kh in hashes:
            candidates.append(r); continue

    resolved_key = None
    resolved_project = None
    for r in candidates:
        p = next((x for x in projects if x.get("id") == r.get("project_id")), None)
        if p and p.get("status") == "active":
            resolved_key = r
            resolved_project = p
            break
    if not resolved_key or not resolved_project:
        audit = _load("service_audit.json")
        audit.append({
            "id": f"a_{int(time.time()*1000)}_{len(audit)+1}",
            "endpoint": "list_tool_results",
            "project_id": None,
            "api_key_id": None,
            "status": "unauthorized",
            "error_code": "unauthorized",
            "error_message": "Invalid/revoked API key or inactive project",
            "response_bytes": 0,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("service_audit.json", audit)
        return _err("UNAUTHORIZED", "Invalid/revoked API key or inactive project")

    # Update last_used_at
    for r in api_keys:
        if r.get("id") == resolved_key.get("id"):
            r["last_used_at"] = now_iso
            r["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    # Request must exist for project
    req = next((x for x in tool_requests if x.get("id") == request_id and x.get("project_id") == resolved_project.get("id")), None)
    if not req:
        audit = _load("service_audit.json")
        audit.append({
            "id": f"a_{int(time.time()*1000)}_{len(audit)+1}",
            "endpoint": "list_tool_results",
            "project_id": resolved_project.get("id"),
            "api_key_id": resolved_key.get("id"),
            "status": "not_found",
            "error_code": "not_found",
            "error_message": "tool request not found",
            "response_bytes": 0,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso,
        })
        _save("service_audit.json", audit)
        return _err("NOT_FOUND", "tool request not found")

    # Cursor: base64("sequence|id")
    def _decode_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(c.encode("ascii") + b"===").decode("utf-8")
            parts = raw.split("|", 1)
            if len(parts) != 2:
                return _err("VALIDATION_ERROR", "Invalid cursor")
            seq = int(parts[0])
            rid = parts[1]
            return (seq, rid)
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    dc = _decode_cursor(cursor)
    if isinstance(dc, dict) and "error" in dc:
        return dc

    boundary = dc  # (sequence, id) exclusive

    # Filter results
    rows = []
    for tr in tool_results:
        if tr.get("request_id") != request_id:
            continue
        if result_kind is not None and tr.get("result_kind") != result_kind:
            continue
        rows.append(tr)

    # Order by sequence asc, then id
    def _sort_key(r):
        seq = r.get("sequence")
        if not isinstance(seq, int):
            seq = 0
        return (seq, str(r.get("id") or ""))

    rows.sort(key=_sort_key)

    if boundary:
        bseq, bid = boundary
        filtered = []
        for r in rows:
            seq, rid = _sort_key(r)
            if seq > bseq:
                filtered.append(r)
            elif seq == bseq and rid > bid:
                filtered.append(r)
        rows = filtered

    page = rows[:page_size]
    has_more = len(rows) > page_size

    next_cursor = None
    if has_more and page:
        last = page[-1]
        seq = last.get("sequence")
        if not isinstance(seq, int):
            seq = 0
        lid = str(last.get("id") or "")
        try:
            next_cursor = base64.urlsafe_b64encode(f"{seq}|{lid}".encode("utf-8")).decode("ascii").rstrip("=")
        except Exception:
            next_cursor = None

    resp = {
        "data": page,
        "meta": {
            "returned": len(page),
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
        }
    }

    # Audit
    try:
        response_bytes = len(json.dumps(resp, ensure_ascii=False).encode("utf-8"))
    except Exception:
        response_bytes = 0
    audit = _load("service_audit.json")
    audit.append({
        "id": f"a_{int(time.time()*1000)}_{len(audit)+1}",
        "endpoint": "list_tool_results",
        "project_id": resolved_project.get("id"),
        "api_key_id": resolved_key.get("id"),
        "status": "succeeded",
        "error_code": None,
        "error_message": None,
        "response_bytes": response_bytes,
        "latency_ms": int((time.time() - t0) * 1000),
        "created_at": now_iso,
    })
    _save("service_audit.json", audit)

    return resp

def scraping_browser_create_session(api_key, ttl_seconds=None, user_agent=None, proxy_country=None, block_resources=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0541000" if __import__("os").path.isdir("./environment_mix/0541000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _log_request(project_id, api_key_id, tool_name, status, response_bytes=None, error_code=None, error_message=None, started_at=None, finished_at=None, extra_fields=None):
        tr = _load("tool_requests.json")
        tid = "tr_" + uuid.uuid4().hex
        row = {
            "id": tid,
            "project_id": project_id,
            "api_key_id": api_key_id,
            "session_id": None,
            "tool_name": tool_name,
            "status": status,
            "engine": None,
            "query": None,
            "cursor": None,
            "url": None,
            "keyword": None,
            "pages_to_search": None,
            "extraction_prompt": None,
            "first_name": None,
            "last_name": None,
            "num_of_reviews": None,
            "days_limit": None,
            "num_of_comments": None,
            "response_content_type": None,
            "response_bytes": response_bytes,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        if isinstance(extra_fields, dict):
            for k, v in extra_fields.items():
                if k in row:
                    row[k] = v
        tr.append(row)
        _save("tool_requests.json", tr)
        return tid

    def _month_key(dt):
        return dt.strftime("%Y-%m")

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _auth_resolve(api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None, None, None, _err("VALIDATION_ERROR", "api_key must be a non-empty string")
        api_key_value = api_key_value.strip()
        keys = _load("api_keys.json")
        projects = _load("projects.json")

        candidates = []
        for k in keys:
            if k.get("status") != "active":
                continue
            # Authenticate by client-visible value: allow either record id or key_prefix match.
            if api_key_value == k.get("id") or api_key_value == k.get("key_prefix"):
                candidates.append(k)

        # Also allow matching "prefix..." style where the first 8 chars equal key_prefix.
        if not candidates and len(api_key_value) >= 8:
            pref = api_key_value[:8]
            for k in keys:
                if k.get("status") != "active":
                    continue
                if pref == k.get("key_prefix"):
                    candidates.append(k)

        # Find a project that is active for any candidate.
        for k in candidates:
            pid = k.get("project_id")
            p = next((x for x in projects if x.get("id") == pid), None)
            if p and p.get("status") == "active":
                return p, k, projects, None

        return None, None, projects, _err("UNAUTHORIZED", "API key is not active or project is not active")

    # Validate inputs
    if ttl_seconds is None:
        ttl_seconds = 900
    if not isinstance(ttl_seconds, int):
        # log attempt if possible? auth required to create any tool_requests row; follow rule: reject and no tool_requests row created.
        return _err("VALIDATION_ERROR", "ttl_seconds must be an integer")
    if ttl_seconds < 60 or ttl_seconds > 86400:
        return _err("VALIDATION_ERROR", "ttl_seconds must be between 60 and 86400")

    if user_agent is not None and not isinstance(user_agent, str):
        return _err("VALIDATION_ERROR", "user_agent must be a string")
    if proxy_country is not None:
        if not isinstance(proxy_country, str):
            return _err("VALIDATION_ERROR", "proxy_country must be a string")
        if not re.fullmatch(r"[A-Za-z]{2}", proxy_country.strip() or ""):
            return _err("VALIDATION_ERROR", "proxy_country must be an ISO-3166-1 alpha-2 code")
        proxy_country = proxy_country.upper()
    if block_resources is None:
        block_resources = False
    if not isinstance(block_resources, bool):
        return _err("VALIDATION_ERROR", "block_resources must be a boolean")

    # Authenticate
    project, key, _projects, auth_err = _auth_resolve(api_key)
    if auth_err:
        return auth_err

    # Enforce plan/quota: plan must allow browser usage (free disallowed here).
    plan = project.get("plan")
    if plan not in ("payg", "enterprise"):
        # Per business rules: exceeding quota yields failed request with error_code='quota_exceeded'
        # Here: plan does not allow browser usage -> QUOTA_EXCEEDED per tool description.
        # No tool_requests row created? Business rule says reject and no tool_requests row created only for inactive auth.
        # So we DO create a failed tool_requests row to observe dynamics.
        _log_request(project.get("id"), key.get("id"), "scraping_browser_create_session", "failed",
                     response_bytes=0, error_code="quota_exceeded", error_message="Plan does not allow browser usage",
                     started_at=now_iso, finished_at=now_iso)
        return _err("QUOTA_EXCEEDED", "Plan does not allow browser usage")

    # Monthly quota checks (requests, bytes, browser actions)
    tool_reqs = _load("tool_requests.json")
    browser_actions = _load("browser_actions.json")
    mkey = _month_key(now)

    req_count = 0
    byte_sum = 0
    browser_action_count = 0

    for r in tool_reqs:
        if r.get("project_id") != project.get("id"):
            continue
        created = _parse_dt(r.get("created_at"))
        if not created:
            continue
        if _month_key(created) != mkey:
            continue
        req_count += 1
        rb = r.get("response_bytes")
        if isinstance(rb, int) and rb >= 0:
            byte_sum += rb

    for a in browser_actions:
        if a.get("project_id") != project.get("id"):
            continue
        created = _parse_dt(a.get("created_at"))
        if not created:
            continue
        if _month_key(created) != mkey:
            continue
        browser_action_count += 1

    if not isinstance(project.get("monthly_request_quota"), int) or project.get("monthly_request_quota") < 0:
        return _err("VALIDATION_ERROR", "Project monthly_request_quota is invalid")
    if not isinstance(project.get("monthly_byte_quota"), int) or project.get("monthly_byte_quota") < 0:
        return _err("VALIDATION_ERROR", "Project monthly_byte_quota is invalid")
    if not isinstance(project.get("monthly_browser_action_quota"), int) or project.get("monthly_browser_action_quota") < 0:
        return _err("VALIDATION_ERROR", "Project monthly_browser_action_quota is invalid")

    if req_count + 1 > project.get("monthly_request_quota"):
        _log_request(project.get("id"), key.get("id"), "scraping_browser_create_session", "failed",
                     response_bytes=0, error_code="quota_exceeded", error_message="Monthly request quota exceeded",
                     started_at=now_iso, finished_at=now_iso)
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded", error_code="quota_exceeded")

    if byte_sum > project.get("monthly_byte_quota"):
        _log_request(project.get("id"), key.get("id"), "scraping_browser_create_session", "failed",
                     response_bytes=0, error_code="quota_exceeded", error_message="Monthly byte quota exceeded",
                     started_at=now_iso, finished_at=now_iso)
        return _err("QUOTA_EXCEEDED", "Monthly byte quota exceeded", error_code="quota_exceeded")

    # Creating session itself is a request; browser action quota applies to actions, not session create.
    # Still enforce plan limits and keep session within plan clamp.
    ttl_clamp = ttl_seconds
    if plan == "payg":
        ttl_clamp = min(ttl_clamp, 3600)
    elif plan == "enterprise":
        ttl_clamp = min(ttl_clamp, 86400)

    # Create tool_request queued -> running -> succeeded (with a result row) to satisfy "succeeded requires results".
    started_iso = now_iso
    req_id = _log_request(project.get("id"), key.get("id"), "scraping_browser_create_session", "queued",
                          response_bytes=None, started_at=None, finished_at=None)

    # Transition queued -> running
    tool_reqs = _load("tool_requests.json")
    req_row = next((x for x in tool_reqs if x.get("id") == req_id), None)
    if not req_row:
        return _err("NOT_FOUND", "Internal request row missing")
    req_row["status"] = "running"
    req_row["started_at"] = started_iso
    req_row["updated_at"] = started_iso
    _save("tool_requests.json", tool_reqs)

    # Create browser session
    sessions = _load("browser_sessions.json")
    sid = "bs_" + uuid.uuid4().hex
    expires = (now + datetime.timedelta(seconds=ttl_clamp)).replace(microsecond=0)
    expires_iso = expires.isoformat() + "Z"
    sess_row = {
        "id": sid,
        "project_id": project.get("id"),
        "api_key_id": key.get("id"),
        "session_id": None,
        "status": "active",
        "current_url": None,
        "current_title": None,
        "history": [],
        "history_index": 0,
        "action_count": 0,
        "last_activity_at": now_iso,
        "expires_at": expires_iso,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    sessions.append(sess_row)
    _save("browser_sessions.json", sessions)

    # Store a result snapshot as session_stats_json? No, tool_results kinds don't include browser session snapshot.
    # We'll store a web_data_json-like payload? Not allowed. Use session_stats_json only for session_stats tool.
    # Here, create a minimal web_data_json is wrong. Instead store extracted_json? wrong.
    # So we record completion by creating a session_stats_json is not semantically correct.
    # Alternative: mark tool_request succeeded with at least one tool_results row: use result_kind="web_data_json" with payload_json containing session creation response.
    # This is the closest JSON result kind used across tools; not constrained by tool_name here. We'll do web_data_json and payload_json snapshot.
    results = _load("tool_results.json")
    rid = "trr_" + uuid.uuid4().hex
    payload = {
        "browser_session_id": sid,
        "status": "active",
        "ttl_seconds": ttl_clamp,
        "expires_at": expires_iso,
        "user_agent": user_agent,
        "proxy_country": proxy_country,
        "block_resources": block_resources
    }
    res_row = {
        "id": rid,
        "request_id": req_id,
        "result_kind": "web_data_json",
        "sequence": 0,
        "source_url": None,
        "title": None,
        "description": None,
        "payload_text": None,
        "payload_json": payload,
        "next_cursor": None,
        "cache_hit": False,
        "fetched_at": now_iso,
        "expires_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    # Enforce uniqueness (request_id, result_kind, sequence)
    if any(r.get("request_id") == req_id and r.get("result_kind") == "web_data_json" and r.get("sequence") == 0 for r in results):
        # Shouldn't happen; idempotency not defined; treat as conflict.
        return _err("CONFLICT", "Result already exists for this request")
    results.append(res_row)
    _save("tool_results.json", results)

    # Finish request as succeeded and compute response_bytes
    finished = datetime.datetime.utcnow().replace(microsecond=0)
    finished_iso = finished.isoformat() + "Z"
    resp_bytes = len(json.dumps(payload, ensure_ascii=False).encode("utf-8"))

    tool_reqs = _load("tool_requests.json")
    req_row = next((x for x in tool_reqs if x.get("id") == req_id), None)
    if not req_row:
        return _err("NOT_FOUND", "Internal request row missing (finalize)")
    req_row["status"] = "succeeded"
    req_row["response_content_type"] = "application/json"
    req_row["response_bytes"] = resp_bytes
    req_row["finished_at"] = finished_iso
    req_row["updated_at"] = finished_iso
    _save("tool_requests.json", tool_reqs)

    # Update api_keys.last_used_at
    keys = _load("api_keys.json")
    krow = next((x for x in keys if x.get("id") == key.get("id")), None)
    if krow:
        krow["last_used_at"] = finished_iso
        krow["updated_at"] = finished_iso
        _save("api_keys.json", keys)

    latency_ms = int((time.time() - t0) * 1000)

    # Return created session state snapshot
    return {
        "browser_session": {
            "id": sid,
            "status": "active",
            "current_url": None,
            "current_title": None,
            "history": [],
            "history_index": 0,
            "action_count": 0,
            "last_activity_at": now_iso,
            "expires_at": expires_iso,
        },
        "request": {
            "id": req_id,
            "status": "succeeded",
            "response_bytes": resp_bytes,
            "latency_ms": latency_ms,
        }
    }

def scraping_browser_close_session(api_key, browser_session_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0541000" if __import__("os").path.isdir("./environment_mix/0541000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(browser_session_id, str) or not browser_session_id.strip():
        return _err("VALIDATION_ERROR", "browser_session_id must be a non-empty string")
    api_key = api_key.strip()
    browser_session_id = browser_session_id.strip()

    projects = _load("projects.json")
    api_keys = _load("api_keys.json")
    browser_sessions = _load("browser_sessions.json")
    tool_requests = _load("tool_requests.json")

    # Authenticate by id/key_prefix/prefix match (never key_hash)
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        kp = k.get("key_prefix")
        if api_key == k.get("id") or api_key == kp or (isinstance(kp, str) and kp and api_key.startswith(kp)):
            key_row = k
            break
    if not key_row:
        return _err("UNAUTHORIZED", "Authentication rule: api_key must resolve to an active api_keys record (matched by id or key_prefix).")

    project = next((p for p in projects if isinstance(p, dict) and p.get("id") == key_row.get("project_id")), None)
    if not project or project.get("status") != "active":
        return _err("UNAUTHORIZED", "Authentication rule: the API key's project must be active.")

    # update last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    sess = next((s for s in browser_sessions if isinstance(s, dict) and s.get("id") == browser_session_id), None)
    if not sess:
        return _err("NOT_FOUND", "Browser session not found.", browser_session_id=browser_session_id)
    if sess.get("project_id") != project.get("id"):
        return _err("UNAUTHORIZED", "Browser session does not belong to the authenticated project.", browser_session_id=browser_session_id)

    if sess.get("status") != "active":
        return _err("INVALID_TRANSITION", "Cannot close browser session: status is not 'active'.", status=sess.get("status"))

    # Transition active -> closed
    for s in browser_sessions:
        if isinstance(s, dict) and s.get("id") == browser_session_id:
            s["status"] = "closed"
            s["updated_at"] = now_iso
            s["last_activity_at"] = now_iso
            sess = s
            break
    _save("browser_sessions.json", browser_sessions)

    # Log invocation (observable dynamics)
    def _gen_id(prefix, existing_ids):
        import uuid
        rid = f"{prefix}_{uuid.uuid4().hex}"
        while rid in existing_ids:
            rid = f"{prefix}_{uuid.uuid4().hex}"
        return rid

    def _json_size_bytes(obj):
        try:
            return len(json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        except Exception:
            return 0

    existing = {r.get("id") for r in tool_requests if isinstance(r, dict)}
    audit_id = _gen_id("bd_req", existing)
    body = {"browser_session": sess}
    rb = _json_size_bytes(body)
    audit = {
        "id": audit_id,
        "project_id": project.get("id"),
        "api_key_id": key_row.get("id"),
        "session_id": sess.get("session_id"),
        "tool_name": "session_stats",
        "status": "succeeded",
        "engine": None,
        "query": None,
        "cursor": None,
        "url": sess.get("current_url"),
        "keyword": None,
        "pages_to_search": None,
        "extraction_prompt": None,
        "first_name": None,
        "last_name": None,
        "num_of_reviews": None,
        "days_limit": None,
        "num_of_comments": None,
        "response_content_type": "application/json",
        "response_bytes": rb,
        "error_code": None,
        "error_message": None,
        "started_at": now_iso,
        "finished_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    tool_requests.append(audit)
    _save("tool_requests.json", tool_requests)

    return {"browser_session": sess, "latency_ms": int((time.time() - t0) * 1000)}
